    TextMapId = "FailureGuidance_Text_1001"
  },
  FailureGuidance_Text_1002 = {
    ContentEN = "Levelling up characters and their skills and equipping them with suitable Demon Wedges will significantly boost their combat capabilities.",
    ContentJP = "キャラクターやスキルをレベルアップし、魔の楔の組み合わせを工夫して、戦闘能力を高めよう。",
    ContentKR = "캐릭터와 스킬 레벨을 올리거나 적합한 악마의 쐐기 조합을 장착하여 캐릭터의 전투 능력을 대폭 상승시킬 수 있습니다.",
    ContentTC = "提升角色等級與技能等級，裝備合適的魔之楔組合，都能大幅提升角色作戰能力。",
    TextMapContent = "提升角色等级与技能等级，装备合适的魔之楔组合，都能大幅提升角色作战能力。",
    TextMapId = "FailureGuidance_Text_1002"
  },
  FailureGuidance_Text_1003 = {
    ContentEN = "Enhancing weapons and equipping them with suitable Demon Wedges can unlock their full potential.",
    ContentJP = "武器をレベルアップし、魔の楔の組み合わせを工夫して、武器の潜在能力を引きだそう。",
    ContentKR = "무기를 레벨업하고 적합한 악마의 쐐기 조합을 장착하여 무기 잠재력을 최대로 끌어올리세요.",
    ContentTC = "提升武器等級，裝備合適的魔之楔組合，以最大程度激發武器潛能。",
