  },
  FailureGuidance_Text_1004 = {
    ContentEN = "The Eclosioner excels in aerial combat. Prioritise <H>ranged weapon</> progression to strike from a distance.",
    ContentJP = "羽化せし者は空中戦に秀でるため、<H>遠隔</>武器を重点的に育成し、遠隔攻撃で対処せよ。",
    ContentKR = "우화를 이룬 자는 강력한 공중 작전 능력을 보유하고 있으므로, <H>원거리</> 무기를 육성하여 원거리 공격으로 대처하는 것을 권장합니다.",
    ContentTC = "羽化者空中作戰能力較強，重點培養<H>遠程</>武器，以遠程攻擊應對。",
    TextMapContent = "羽化者空中作战能力较强，重点培养<H>远程</>武器，以远程攻击应对。",
    TextMapId = "FailureGuidance_Text_1004"
