  HomePianoDes_1001001 = {
    ContentEN = "Bathed in twilight, we sailed through the boundless dark — together, ever onward, toward the dawn.",
    ContentJP = "黄昏に染まり、果てなき闇夜を駆け抜け、そして共に明日へ。",
    ContentKR = "황혼에 젖어, 끝없는 밤을 가로질러 함께 내일로 나아간다.",
    ContentTC = "曆經暮色的浸洗，駛過無垠的黑夜，而後，一起去往明天。",
    TextMapContent = "历经暮色的浸洗，驶过无垠的黑夜，而后，一起去往明天。",
    TextMapId = "HomePianoDes_1001001"
  },
  HomePianoDes_1001002 = {
    ContentEN = "Destiny lurks behind the dust and sand.",
    ContentJP = "運命はいつも砂塵の後ろに。",
    ContentKR = "운명은 먼지와 모래 뒤에 숨어 있다.",
    ContentTC = "命運站在塵沙的背後。",
    TextMapContent = "命运站在尘沙的背后。",
    TextMapId = "HomePianoDes_1001002"
  },
  HomePianoDes_1001003 = {
    ContentEN = "Never look back.",
    ContentJP = "もう後戻りはできない。",
    ContentKR = "뒤돌아볼 수 없다.",
    ContentTC = "無法回頭。",
    TextMapContent = "无法回头。",
    TextMapId = "HomePianoDes_1001003"
  },
  HomePianoDes_1001004 = {
    ContentEN = "The island was once a haven of tranquility, until it faded into memory.",
    ContentJP = "思い出になるまで、あの島は穏やかで安らかな場所だった。",
    ContentKR = "그 작은 섬은 한때 평온의 안식처였지만, 이제 기억으로만 남았다.",
    ContentTC = "那座小島曾經平靜安寧，直至它成為回憶。",
    TextMapContent = "那座小岛曾经平静安宁，直至它成为回忆。",
    TextMapId = "HomePianoDes_1001004"
  },
  HomePianoDes_1001005 = {
    ContentEN = "As the first mist of morning rises, so too do you set out.",
    ContentJP = "朝霧が立ちのぼるとき、君もまた新たな道へと踏み出すだろう。",
    ContentKR = "안개가 걷히기 시작할 무렵, 그대는 길을 떠나리라.",
    ContentTC = "晨霧初起時，你也將踏上前路。",
    TextMapContent = "晨雾初起时，你也将踏上前路。",
    TextMapId = "HomePianoDes_1001005"
  },
  HomePianoDes_1001006 = {
    ContentEN = "Till the day we meet again.",
    ContentJP = "いつか再び、私たちは巡り会う。",
    ContentKR = "우리가 다시 만날 때까지.",
    ContentTC = "直至我們再次相逢。",
    TextMapContent = "直至我们再次相逢。",
    TextMapId = "HomePianoDes_1001006"
  },
  HomePianoDes_1002001 = {
    ContentEN = "No one knows whether being watched by the Goddess of Fate is a blessing or a curse.",
    ContentJP = "運命の女神に見つめられているのは幸運か不幸か誰にも知らない。",
    ContentKR = "운명의 여신이 지켜보는 게 복인지 불운인지, 아무도 알 수 없다.",
    ContentTC = "無人知曉被命運女神注視究竟是幸運還是不幸。",
    TextMapContent = "无人知晓被命运女神注视究竟是幸运还是不幸。",
    TextMapId = "HomePianoDes_1002001"
  },
  HomePianoDes_1002002 = {
    ContentEN = "We beseech fate to look kindly upon us.",
    ContentJP = "願わくば、運命よ、我らに慈悲を。",
    ContentKR = "운명이 우리에게 은총을 내리길 바라며.",
    ContentTC = "祈請命運垂愛我等。",
    TextMapContent = "祈请命运垂爱我等。",
    TextMapId = "HomePianoDes_1002002"
  },
  HomePianoDes_1002003 = {
    ContentEN = "We beseech fate to look kindly upon us — or else raise our swords against it.",
    ContentJP = "願わくば、運命よ、我らに慈悲を。――あるいは、剣を抜き運命へと挑むか。",
    ContentKR = "운명이 우리에게 은총을 내리길 바라거나... 혹은, 운명을 향해 검을 겨누거나.",
    ContentTC = "祈請命運垂愛我等。或者，向命運執起利劍。",
    TextMapContent = "祈请命运垂爱我等。或者，向命运执起利剑。",
    TextMapId = "HomePianoDes_1002003"
  },
  HomePianoDes_1003001 = {
    ContentEN = "Hand in hand, they flee — chasing a single sliver of hope.",
    ContentJP = "手を取り合い逃げ延びる、わずかな生の光を追いかけて。",
    ContentKR = "가느다란 생존의 희망을 좇아 손을 잡고 도망친다.",
    ContentTC = "手牽手逃亡，追趕一線生機。",
    TextMapContent = "手牵手逃亡，追赶一线生机。",
    TextMapId = "HomePianoDes_1003001"
  },
  HomePianoDes_1003002 = {
    ContentEN = "Treading the knife's edge of the past.",
    ContentJP = "過ぎ去りし日の刃先を歩むように。",
    ContentKR = "과거라는 칼날 위를 걸으며.",
    ContentTC = "行於往事的刀尖。",
    TextMapContent = "行于往事的刀尖。",
    TextMapId = "HomePianoDes_1003002"
  },
  HomePianoDes_1003003 = {
    ContentEN = "The struggle of a cornered beast.",
    ContentJP = "追われた獣たちの戦い。",
    ContentKR = "궁지에 몰린 짐승의 싸움.",
    ContentTC = "困獸之鬥。",
    TextMapContent = "困兽之斗。",
    TextMapId = "HomePianoDes_1003003"
  },
  HomePianoDes_1003004 = {
    ContentEN = "If you wish to save all this.",
    ContentJP = "もし君がすべてを救いたいと願うのなら。",
    ContentKR = "이 모든 걸 구원하기를 갈망한다면.",
    ContentTC = "若你想要拯救這一切。",
    TextMapContent = "若你想要拯救这一切。",
    TextMapId = "HomePianoDes_1003004"
  },
  HomePianoDes_1004001 = {
    ContentEN = "That door does not welcome strangers.",
    ContentJP = "その扉は、見知らぬ者を歓迎しない。",
    ContentKR = "그 문은 낯선 방문자를 환영하지 않는다.",
    ContentTC = "那扇門不歡迎陌生人的造訪。",
    TextMapContent = "那扇门不欢迎陌生人的造访。",
    TextMapId = "HomePianoDes_1004001"
  },
  HomePianoDes_1004002 = {
    ContentEN = "Endless cold and driving snow stand the surest watch upon its walls.",
    ContentJP = "長き厳冬と吹雪こそが、最も忠実な番人である。",
    ContentKR = "끝없는 혹한과 눈보라가 그것의 가장 충실한 수호자이다.",
    ContentTC = "漫長的嚴寒與風雪是它最忠實的戍衛者。",
    TextMapContent = "漫长的严寒与风雪是它最忠实的戍卫者。",
    TextMapId = "HomePianoDes_1004002"
  },
  HomePianoDes_1004003 = {
    ContentEN = "Before the final destination is reached, this place will always be home.",
    ContentJP = "終点に辿り着くまで、ここはいつも居場所。",
    ContentKR = "종점에 닿기 전까지 이곳은 영원한 휴식처다.",
    ContentTC = "在抵達終點前，這裡永遠是歸處。",
    TextMapContent = "在抵达终点前，这里永远是归处。",
    TextMapId = "HomePianoDes_1004003"
  },
  HomePianoDes_1004004 = {
    ContentEN = "A barbed exchange makes quite the opening remarks.",
    ContentJP = "刀を合わせることもまた、悪くない始まりかもしれない。",
    ContentKR = "팽팽한 대치도 나쁘지 않은 시작이다.",
    ContentTC = "針鋒相對或許也是個相當不錯的開頭。",
    TextMapContent = "针锋相对或许也是个相当不错的开头。",
    TextMapId = "HomePianoDes_1004004"
  },
  HomePianoDes_1004005 = {
    ContentEN = "Congratulations — you've won the chance of running into your {性别:brother from another mother|sister from another mister}.",
    ContentJP = "月狩り人のひとりが選ばれ、思いがけず異母（父）{性别:兄弟|姉妹}と出会う。",
    ContentKR = "행운의 월석 사냥꾼 1명을 랜덤으로 추첨해 피보다 진한 {성별: 형제|자매}를 만나게 한다.",
    ContentTC = "隨機抽取一位幸運狩月人偶遇與自己異父異母的{性别:親兄弟|親姐妹}。",
    TextMapContent = "随机抽取一位幸运狩月人偶遇与自己异父异母的{性别：亲兄弟|亲姐妹}。",
    TextMapId = "HomePianoDes_1004005"
  },
  HomePianoDes_1004006 = {
    ContentEN = "Drinks, commissions, rumours, secrets — everything that can be traded changes hands here.",
    ContentJP = "酒、依頼、風聞、秘密……人々はここで交換できるものすべてを取引する。",
    ContentKR = "술, 의뢰, 소문, 비밀… 사람들은 여기서 그들이 교환할 수 있는 모든 것을 거래한다.",
    ContentTC = "酒水、委托、傳聞、秘密……人們在這裡交易他們可以交換的一切。",
    TextMapContent = "酒水、委托、传闻、秘密……人们在这里交易他们可以交换的一切。",
    TextMapId = "HomePianoDes_1004006"
  },
  HomePianoDes_1004007 = {
    ContentEN = "A house where secrets slumber.",
    ContentJP = "秘密が眠る館。",
    ContentKR = "비밀을 숨긴 저택.",
    ContentTC = "沉眠著秘密的宅邸。",
    TextMapContent = "沉眠着秘密的宅邸。",
    TextMapId = "HomePianoDes_1004007"
  },
  HomePianoDes_1004008 = {
    ContentEN = "Home, sweet home. There's nothing like it.",
    ContentJP = "家ほど甘美なものはない。",
    ContentKR = "집보다 더 달콤한 것은 없다.",
    ContentTC = "沒有什麼比家更甜蜜。",
    TextMapContent = "没有什么比家更甜蜜。",
    TextMapId = "HomePianoDes_1004008"
  },
  HomePianoDes_1005001 = {
    ContentEN = "A novice Phoxhunter's first taste of fortune.",
    ContentJP = "新米月狩り人が手にする最初の金。",
    ContentKR = "초보 월석 사냥꾼의 첫 보수.",
    ContentTC = "新手狩月人的第一桶金。",
    TextMapContent = "新手狩月人的第一桶金。",
    TextMapId = "HomePianoDes_1005001"
  },
  HomePianoDes_1005002 = {
    ContentEN = "The beginning of a long trek.",
    ContentJP = "長き旅路の始まり。",
    ContentKR = "긴 여정의 시작점.",
    ContentTC = "一場漫長跋涉的起點。",
    TextMapContent = "一场漫长跋涉的起点。",
    TextMapId = "HomePianoDes_1005002"
  },
  HomePianoDes_1005003 = {
    ContentEN = "In the howling gale, you count every step towards her.",
    ContentJP = "吹き荒ぶ風の中、君は彼女に近づく一歩一歩を数えている。",
    ContentKR = "휘몰아치는 바람 속에서, 그대는 그녀에게 다가가는 걸음 하나하나를 세어간다.",
    ContentTC = "狂風呼嘯間，你細數著向她走近的每一步。",
    TextMapContent = "狂风呼啸间，你细数着向她走近的每一步。",
    TextMapId = "HomePianoDes_1005003"
  },
  HomePianoDes_1005004 = {
    ContentEN = "In retrospect, you know it was a tale of the brave.",
    ContentJP = "再び思い出すとき、それは勇者たちの物語だと知るだろう。",
    ContentKR = "그때를 다시 떠올릴 때, 그대는 그것이 용감한 이들의 이야기였음을 알리라.",
    ContentTC = "當再回憶起那時，你知道這是勇敢者們的故事。",
    TextMapContent = "当再回忆起那时，你知道这是勇敢者们的故事。",
    TextMapId = "HomePianoDes_1005004"
  },
  HomePianoDes_1005005 = {
    ContentEN = "If you gaze long into an abyss, the abyss also gazes into you.",
    ContentJP = "汝が深淵を見つめるとき、深淵もまた汝を見つめ返す。",
    ContentKR = "당신이 심연을 바라볼 때, 심연 또한 당신을 바라보고 있다.",
    ContentTC = "當你凝視深淵，深淵也在凝視著你。",
    TextMapContent = "当你凝视深渊，深渊也在凝视着你。",
    TextMapId = "HomePianoDes_1005005"
  },
  HomePianoDes_1005006 = {
    ContentEN = "We laugh when we speak of death, and weep as we go on living.",
    ContentJP = "人はいつも笑って死を語り、泣きながら生を歩む。",
    ContentKR = "사람들은 늘 웃으면서 죽음을 이야기하고, 울면서 삶을 살아간다.",
    ContentTC = "人們總是笑著談死，哭著去活。",
    TextMapContent = "人们总是笑着谈死，哭着去活。",
    TextMapId = "HomePianoDes_1005006"
  },
  HomePianoDes_1005007 = {
    ContentEN = "He brings death — and life as well.",
    ContentJP = "彼は死をもたらし、同時に生をもたらす。",
    ContentKR = "그는 죽음, 또는 생을 가져온다.",
    ContentTC = "他帶來死，亦帶來生。",
    TextMapContent = "他带来死，亦带来生。",
    TextMapId = "HomePianoDes_1005007"
  },
  HomePianoDes_1005008 = {
    ContentEN = "Lost traveller, return to that dream — the Avian Spirit never left.",
    ContentJP = "迷える旅人よ、夢へと還れ。霊鳥は決して離れてはいない。",
    ContentKR = "방황하는 여행자여, 그 꿈속으로 돌아가라. 영혼의 새는 떠난 적이 없으니.",
    ContentTC = "迷惘的旅人，回到那片夢吧，靈鳥不曾離開。",
    TextMapContent = "迷惘的旅人，回到那片梦吧，灵鸟不曾离开。",
    TextMapId = "HomePianoDes_1005008"
  },
  HomePianoDes_1005009 = {
    ContentEN = "Lost traveller, leave this dream now — the Avian Spirit has taken flight.",
    ContentJP = "迷える旅人よ、夢を去れ。霊鳥はすでに遠くへ飛び去った。",
    ContentKR = "방황하는 여행자여, 이 꿈을 떠나라. 영혼의 새는 이미 먼 여행을 떠났으니.",
    ContentTC = "迷惘的旅人，離開這片夢吧，靈鳥已經遠行。",
    TextMapContent = "迷惘的旅人，离开这片梦吧，灵鸟已经远行。",
    TextMapId = "HomePianoDes_1005009"
  },
  HomePianoDes_1006001 = {
    ContentEN = "They say Icelake has no summer. You think otherwise.",
    ContentJP = "人々は皆、アイスレイク城に夏はないと思っている――だが君は違う。",
    ContentKR = "사람들은 아이스레이크 시티에 여름이 없다고들 하지만, 당신에게는 그렇지 않다.",
    ContentTC = "人們總是認為冰湖城沒有夏天，你則不然。",
    TextMapContent = "人们总是认为冰湖城没有夏天，你则不然。",
    TextMapId = "HomePianoDes_1006001"
  },
  HomePianoDes_1006002 = {
    ContentEN = "Even a mayfly has the right to dream.",
    ContentJP = "か弱きカゲロウにも、夢を見る権利がある。",
    ContentKR = "하찮은 하루살이도 꿈을 꿀 권리가 있다.",
    ContentTC = "渺小的蜉蝣也有夢想的權利。",
    TextMapContent = "渺小的蜉蝣也有梦想的权利。",
    TextMapId = "HomePianoDes_1006002"
  },
  HomePianoDes_1006003 = {
    ContentEN = "That flower has yet to come into its own.",
    ContentJP = "あの花は、まだ咲ききってはいない。",
    ContentKR = "아직 제대로 피지 못한 꽃이다.",
    ContentTC = "那朵花還沒有開好。",
    TextMapContent = "那朵花还没有开好。",
    TextMapId = "HomePianoDes_1006003"
  },
  HomePianoDes_1006004 = {
    ContentEN = "The camera is the finest hunter — only it can catch slippery time.",
    ContentJP = "カメラは最良の狩人――狡猾に逃げゆく時の瞬きを捉えられるのは、それだけだ。",
    ContentKR = "카메라는 뛰어난 사냥꾼이다. 오직 카메라만이 교활한 시간을 포착할 수 있다.",
    ContentTC = "相機是最優秀的獵手，唯有它能捕獲狡猾的光陰。",
    TextMapContent = "相机是最优秀的猎手，唯有它能捕获狡猾的光阴。",
    TextMapId = "HomePianoDes_1006004"
  },
  HomePianoDes_1006005 = {
    ContentEN = "All light races toward its extinguishing.",
    ContentJP = "あらゆる光は、やがて消えゆく運命に向かって駆け抜けていく。",
    ContentKR = "모든 빛이 소멸을 향해 날아간다.",
    ContentTC = "所有光都在向著熄滅飛逝。",
    TextMapContent = "所有光都在向着熄灭飞逝。",
    TextMapId = "HomePianoDes_1006005"
  },
  HomePianoDes_1006006 = {
    ContentEN = "The story of her life.",
    ContentJP = "彼女の一生。",
    ContentKR = "그녀의 일생이다.",
    ContentTC = "她的一生。",
    TextMapContent = "她的一生。",
    TextMapId = "HomePianoDes_1006006"
  },
  HomePianoDes_1006007 = {
    ContentEN = "The meaning of \"death\"?",
    ContentJP = "「死」の意味とは？",
    ContentKR = "'죽음'의 의미란?",
    ContentTC = "「死」的意義？",
    TextMapContent = "“死”的意义？",
    TextMapId = "HomePianoDes_1006007"
  },
  HomePianoDes_1006008 = {
    ContentEN = "The meaning of \"life\"?",
    ContentJP = "「生」の意味とは？",
    ContentKR = "'삶'의 의미란?",
    ContentTC = "「生」的意義？",
    TextMapContent = "“生”的意义？",
    TextMapId = "HomePianoDes_1006008"
  },
  HomePianoDes_1006009 = {
    ContentEN = "Her answer.",
    ContentJP = "彼女の答え。",
    ContentKR = "그녀의 대답이다.",
    ContentTC = "她的回答。",
    TextMapContent = "她的回答。",
    TextMapId = "HomePianoDes_1006009"
  },
  HomePianoDes_1006010 = {
    ContentEN = "Blooming upon frozen earth.",
    ContentJP = "凍土に咲き誇る花。",
    ContentKR = "얼어붙은 땅 위에서 피어나리.",
    ContentTC = "綻於凍土之上。",
    TextMapContent = "绽于冻土之上。",
    TextMapId = "HomePianoDes_1006010"
  },
  HomePianoDes_1007001 = {
    ContentEN = "For the fierce battle soon to come.",
    ContentJP = "迫り来る激戦のために。",
    ContentKR = "곧 시작될 격전을 위하여.",
    ContentTC = "為了即將到來的激戰。",
    TextMapContent = "为了即将到来的激战。",
    TextMapId = "HomePianoDes_1007001"
  },
  HomePianoDes_1007002 = {
    ContentEN = "Advancing through the belly of the iron behemoth.",
    ContentJP = "鋼鉄の巨獣の腹の中を進む。",
    ContentKR = "강철 괴물의 뱃속에서 행진하라.",
    ContentTC = "行進在鋼鐵巨獸的腹中。",
    TextMapContent = "行进在钢铁巨兽的腹中。",
    TextMapId = "HomePianoDes_1007002"
  },
  HomePianoDes_1007003 = {
    ContentEN = "A lifeblood called Phoxichor courses through every vein of Hyperborea.",
    ContentJP = "イコルと呼ばれる血は、ヒュペリアのすべての血管を流れている。",
    ContentKR = "폭시코르라고 불리는 피가 휘페르보레아 제국의 모든 혈관에 흐른다.",
    ContentTC = "名叫月髓的血液，在海伯利亞的每一根血管流淌。",
    TextMapContent = "名叫月髓的血液，在海伯利亚的每一根血管流淌。",
    TextMapId = "HomePianoDes_1007003"
  },
  HomePianoDes_1007004 = {
    ContentEN = "No one knows where the next bullet will come from.",
    ContentJP = "次の弾丸がどこから来るのか、誰にも分からない。",
    ContentKR = "다음 탄환이 어디서 날아올지 아는 사람은 아무도 없다.",
    ContentTC = "無人知曉下一顆子彈將來自何方。",
    TextMapContent = "无人知晓下一颗子弹将来自何方。",
    TextMapId = "HomePianoDes_1007004"
  },
  HomePianoDes_1007005 = {
    ContentEN = "Be brave, and live on — together.",
    ContentJP = "共に生き延びよう。",
    ContentKR = "함께 살아가자.",
    ContentTC = "一起活下去。",
    TextMapContent = "一起活下去。",
    TextMapId = "HomePianoDes_1007005"
  },
  HomePianoDes_1007006 = {
    ContentEN = "Until the mask is lifted, none can tell whether it hides the face of an angel or a demon.",
    ContentJP = "仮面が剥がれるまで、その裏が天使か悪魔かを知る者はいない。",
    ContentKR = "가면이 벗겨지기 전에는 그 뒤에 있는 것이 천사인지, 악마인지 아무도 모른다.",
    ContentTC = "面具揭開前，無人知曉它的後面是天使還是魔鬼。",
    TextMapContent = "面具揭开前，无人知晓它的后面是天使还是魔鬼。",
    TextMapId = "HomePianoDes_1007006"
  },
  HomePianoDes_1007007 = {
    ContentEN = "\"It's raining tonight in Dismania.\"",
    ContentJP = "「ディズマニアの今夜は雨だ。」",
    ContentKR = "\"디즈마니아는 오늘 밤 비가 오겠습니다.\"",
    ContentTC = "「迪斯瑪尼亞今夜有雨。」",
    TextMapContent = "“迪斯玛尼亚今夜有雨。”",
    TextMapId = "HomePianoDes_1007007"
  },
  HomePianoDes_1007008 = {
    ContentEN = "Clear skies will come.",
    ContentJP = "やがて晴れの日は訪れる。",
    ContentKR = "곧 맑게 갠 날이 올 것이다.",
    ContentTC = "晴日將到來。",
    TextMapContent = "晴日将到来。",
    TextMapId = "HomePianoDes_1007008"
  },
  HomePianoDes_1007009 = {
    ContentEN = "In the name of justice, the inquisitor casts down a trial by fire.",
    ContentJP = "正義の名のもとに、裁きの火が降り注ぐ。",
    ContentKR = "심판자가 정의의 이름으로 불의 시련을 내린다.",
    ContentTC = "以正義的名義，審判者投下烈火的試煉。",
    TextMapContent = "以正义的名义，审判者投下烈火的试炼。",
    TextMapId = "HomePianoDes_1007009"
  },
  HomePianoDes_1008001 = {
    ContentEN = "Her wandering may well have traced the breadth of Atlasia a hundred times over.",
    ContentJP = "彼女の彷徨の足跡が、アトラシアを幾周できるかを知る者はいない。",
    ContentKR = "방랑하는 그녀의 발걸음이 아트라시아를 몇 바퀴나 돌았을까?",
    ContentTC = "沒有人知道她流浪過的足跡可以環遊阿特拉西亞多少圈。",
    TextMapContent = "没有人知道她流浪过的足迹可以环游阿特拉西亚多少圈。",
    TextMapId = "HomePianoDes_1008001"
  },
  HomePianoDes_1009001 = {
    ContentEN = "Weave logic into a web to catch a shard of truth.",
    ContentJP = "論理の網を張り巡らせ、真実の一端を垣間見る。",
    ContentKR = "논리를 그물로 진실의 일각을 엿보리라.",
    ContentTC = "以邏輯織網，窺見真相一隅。",
    TextMapContent = "以逻辑织网，窥见真相一隅。",
    TextMapId = "HomePianoDes_1009001"
  },
  HomePianoDes_1009002 = {
    ContentEN = "Young, ardent hearts throb for a future in full colour.",
    ContentJP = "若く熱き心臓は高鳴る、きらめく未来のために。",
    ContentKR = "젊고 뜨거운 심장이 찬란한 미래를 위하여 요동친다.",
    ContentTC = "年輕而熱忱的心髒鼓動著，為了五光十色的未來。",
    TextMapContent = "年轻而热忱的心脏鼓动着，为了五光十色的未来。",
    TextMapId = "HomePianoDes_1009002"
  },
  HomePianoDes_1009003 = {
    ContentEN = "Even the finest drama is but a fragment of life.",
    ContentJP = "最良の演劇でさえ、人生の縮図にすぎない。",
    ContentKR = "가장 좋은 연극 또한 인생의 축소판에 불과하다.",
    ContentTC = "最好的戲劇也不過是人生的縮影。",
    TextMapContent = "最好的戏剧也不过是人生的缩影。",
    TextMapId = "HomePianoDes_1009003"
  },
  HomePianoDes_1009004 = {
    ContentEN = "We are all in the gutter, but some of us are looking at the stars.",
    ContentJP = "我らは溝の中に生きる――それでも、星空を仰ぎ見る者がいる。",
    ContentKR = "우리는 진창 속에서 살고 있지만, 여전히 누군가는 별하늘을 바라본다.",
    ContentTC = "我們生活在溝渠裡，但仍有人仰望星空。",
    TextMapContent = "我们生活在沟渠里，但仍有人仰望星空。",
    TextMapId = "HomePianoDes_1009004"
  },
  HomePianoDes_1009005 = {
    ContentEN = "Look up again — only phantoms refracted in shattered glass.",
    ContentJP = "再び仰ぎ見れば、そこには砕けたガラスに映る幻影のみ。",
    ContentKR = "다시금 고개를 들었지만, 깨진 유리 조각에 비치는 환영만이 보인다.",
    ContentTC = "再度仰望，唯見碎玻璃折射的幻影。",
    TextMapContent = "再度仰望，唯见碎玻璃折射的幻影。",
    TextMapId = "HomePianoDes_1009005"
  },
  HomePianoDes_1009006 = {
    ContentEN = "If we are forsaken by the gods, where then is redemption?",
    ContentJP = "もし我らが神々に見捨てられし子なら、救済はいずこにあるのか。",
    ContentKR = "우리가 신의 버림을 받았다면, 구원은 어디에 있는 걸까?",
    ContentTC = "若我們是神明的棄子，那救贖又在何處？",
    TextMapContent = "若我们是神明的弃子，那救赎又在何处？",
    TextMapId = "HomePianoDes_1009006"
  },
  HomePianoDes_1009007 = {
    ContentEN = "For the first time, I open my heart and embrace the world's gentle indifference.",
    ContentJP = "初めて、心を開き、世界の優しき冷淡を抱きしめた。",
    ContentKR = "처음으로 마음을 열고 세상의 다정한 무관심을 포옹한다.",
    ContentTC = "第一次，我敞開心扉，擁抱世界溫柔的冷漠。",
    TextMapContent = "第一次，我敞开心扉，拥抱世界温柔的冷漠。",
    TextMapId = "HomePianoDes_1009007"
  },
  HomePianoDes_1009008 = {
    ContentEN = "Only the snow remembers.",
    ContentJP = "白雪だけが覚えている。",
    ContentKR = "흰 눈만이 기억하리라.",
    ContentTC = "只有白雪記得。",
    TextMapContent = "只有白雪记得。",
    TextMapId = "HomePianoDes_1009008"
  },
