  MOD_DESC_104001 = {
    ContentEN = "Upgrades the Dual Blades Sliding Attack into a lethal dash, slashing through all enemies in your path for double the damage of the standard attack.",
    ContentJP = "双剣のスライディング攻撃のモーションと威力を変更する。前方に突進し、ルード上の敵にダメージを与える。スキルの通常モードと比べ、総合威力が100%アップする。",
    ContentKR = "쌍도 슬라이딩 공격 패턴과 위력을 변화시켜, 앞으로 돌진하고 경로의 모든 적에게 대미지를 입힌다. 기본 방법에 비해, 종합 위력이 100% 상승한다.",
    ContentTC = "改變雙刀的滑鏟攻擊招式和威力，向前衝刺並對沿途的所有敵人造成傷害。對比默認招式，綜合威力提高100%。",
    TextMapContent = "改变双刀的滑铲攻击招式和威力，向前冲刺并对沿途的所有敌人造成伤害。对比默认招式，综合威力提高100%。",
    TextMapId = "MOD_DESC_104001"
  },
  MOD_DESC_104002 = {
    ContentEN = "Upgrades Dual Blades Normal Attack to combine the blades into a returning throw. Deals double the damage of the standard attack.",
    ContentJP = "双剣の通常攻撃モーションと威力を変更する。双剣を組み合わせて回転攻撃を行う。スキルの通常モードと比べ、総合威力が100%アップする。",
    ContentKR = "쌍도의 기본 공격 패턴과 위력을 변경하고 쌍도를 조합하여 회전 공격을 발동한다. 기본 패턴에 비해 종합 위력이 100% 상승한다.",
    ContentTC = "改變雙刀的普通攻擊招式和威力。將雙刀組合後進行回旋攻擊。對比默認招式，綜合威力提高100%。",
    TextMapContent = "改变双刀的普通攻击招式和威力。将双刀组合后进行回旋攻击。对比默认招式，综合威力提高100%。",
    TextMapId = "MOD_DESC_104002"
