  },
  MonsterRushEvent_Wuyou_DungeonName07 = {
    ContentEN = "A Tomorrow Unburdened",
    ContentJP = "ゆらめく明日",
    ContentKR = "여유로운 내일",
    ContentTC = "悠然飄搖的明日",
    TextMapContent = "悠然飘摇的明日",
    TextMapId = "MonsterRushEvent_Wuyou_DungeonName07"
  },
  MonsterRushEvent_Wuyou_PetDesc_1 = {
    ContentEN = "A Wishen who wields destructive talismans with ease — though the real mystery is where they're pulling them from.",
    ContentJP = "符箓を自在に操るムユウセイ。ただ破壊力以上に気になるのは、その尽きることない符箓がどこから出てくるのかだ。",
    ContentKR = "부적을 다루는 데 능한 무유생. 부적의 파괴력도 대단하지만 끝없이 나오는 그 부적은 도대체 어디서 꺼내는 건지 더 궁금하다.",
    ContentTC = "擅使符籙的無由生，不過相比於其破壞力，你更好奇它那幾乎無窮無盡的符籙是從哪裡拿出來的。",
    TextMapContent = "擅使符箓的无由生，不过相比于其破坏力，你更好奇它那几乎无穷无尽的符箓是从哪里拿出来的。",
    TextMapId = "MonsterRushEvent_Wuyou_PetDesc_1"
  },
  MonsterRushEvent_Wuyou_PetDesc_2 = {
    ContentEN = "He seems calm, composed — but cross him, and the consequences may far exceed your expectations.",
    ContentJP = "とても落ち着いて見えるムユウセイ。しかし、もし怒らせてしまったなら、その結果は想像を超えるかもしれない。",
    ContentKR = "차분해 보이는 무유생. 단, 화나게 하면 상상할 수 없는 결과를 초래할 수도 있다.",
    ContentTC = "看起來十分沉穩的無由生，但據說如果惹到他生氣，會有難以預想的後果。",
    TextMapContent = "看起来十分沉稳的无由生，但据说如果惹到他生气，会有难以预想的后果。",
    TextMapId = "MonsterRushEvent_Wuyou_PetDesc_2"
  },
  MonsterRushEvent_Wuyou_PetDesc_3 = {
    ContentEN = "A master of sword-flight, their blades drift and whirl with effortless grace — the perfect backdrop for a photo, if they'd let you borrow it.",
    ContentJP = "剣術に優れたムユウセイ。周囲を巡る剣は撮影用の背景にぴったりで、次はぜひお願いしてみたいところだ。",
    ContentKR = "검술에 능한 무유생. 주변을 맴도는 검은, 기념샷을 찍기 완벽한 배경이다. 다음에 한 번 부탁해 봐도 되려나?",
    ContentTC = "善於禦劍的無由生，環繞周身的劍很適合用作留影的布景，也許下次可以試著拜托它一下。",
    TextMapContent = "善于御剑的无由生，环绕周身的剑很适合用作留影的布景，也许下次可以试着拜托它一下。",
    TextMapId = "MonsterRushEvent_Wuyou_PetDesc_3"
  },
  MonsterRushEvent_Wuyou_PetDesc_4 = {
    ContentEN = "They always drift with a light, unhurried grace — and if you're feeling down, a gentle pat from them might just lift your spirits.",
    ContentJP = "いつも気ままでゆったりしたムユウセイ。機嫌が悪いときは、頭をなでれば落ち着いてくれるかもしれない。",
    ContentKR = "늘 느긋해 보이는 무유생. 기분이 안 좋을 때 머리를 쓰다듬어 주면 훨씬 나아질지도?",
    ContentTC = "總是輕飄飄慢悠悠的無由生，心情不好的話，找她摸摸頭頂應該就會舒緩不少吧。",
    TextMapContent = "总是轻飘飘慢悠悠的无由生，心情不好的话，找她摸摸头顶应该就会舒缓不少吧。",
    TextMapId = "MonsterRushEvent_Wuyou_PetDesc_4"
  },
