  NpcBiography_AgeText = {
    ContentEN = "Age",
    ContentJP = "年齢",
    ContentKR = "연령：",
    ContentTC = "年齡",
    TextMapContent = "年龄",
    TextMapId = "NpcBiography_AgeText"
