  PhantomTalk_3202_Chest = {
    ContentEN = "Luck is another means of accumulating wealth. Go on — there's no shame in accepting it.",
    ContentJP = "運もまた、財を成す手段のひとつよ。さあ、これを受け取って。",
    ContentKR = "행운도 재산을 모으는 방법이에요, 이건 받아 둬요.",
    ContentTC = "幸運也是積攢財富的手段，收下這些東西吧。",
    TextMapContent = "幸运也是积攒财富的手段，收下这些东西吧。",
    TextMapId = "PhantomTalk_3202_Chest"
  },
  PhantomTalk_3301_Chest = {
    ContentEN = "I smell treasure! Feels like a good haul today!",
    ContentJP = "宝物のにおいがする！今日も大収穫だよーっ！",
    ContentKR = "보물의 냄새가 나요, 오늘도 대풍년이네요!",
    ContentTC = "我聞到了寶物的氣息，今天也是大豐收！",
    TextMapContent = "我闻到了宝物的气息，今天也是大丰收！",
    TextMapId = "PhantomTalk_3301_Chest"
  },
  PhantomTalk_4101_Chest = {
    ContentEN = "Perimeter clear. Recovered some abandoned supplies.",
    ContentJP = "周囲の偵察完了、遺物をいくつか発見しました。",
    ContentKR = "주변 탐색 완료, 몇 가지 남은 물자를 발견했습니다.",
    ContentTC = "周邊探查完畢，發現一些遺留的物資。",
    TextMapContent = "周边探查完毕，发现一些遗留的物资。",
    TextMapId = "PhantomTalk_4101_Chest"
  },
  PhantomTalk_4102_Chest = {
    ContentEN = "Earth below, fire above — gold, born of toil. The signs did not deceive.",
    ContentJP = "地を耕して金を得る……まさに天地の理ね。来た甲斐があったわ。",
    ContentKR = "아래는 땅, 위는 불, 땅을 갈아 금을 얻다니, 헛되지 않았군.",
    ContentTC = "下坤上離、鋤地生金，果然不虛此行。",
    TextMapContent = "下坤上离、锄地生金，果然不虚此行。",
    TextMapId = "PhantomTalk_4102_Chest"
  },
  PhantomTalk_4201_Chest = {
    ContentEN = "Such worldly things are of no use to me. They're yours.",
    ContentJP = "このような身の回りの物は俺には不要だ。あんたが受け取ってくれ。",
    ContentKR = "이런 바깥 물건은 내겐 쓸모없으니, 네가 가져.",
    ContentTC = "這等身外之物與我無用，由你收下吧。",
    TextMapContent = "这等身外之物与我无用，由你收下吧。",
    TextMapId = "PhantomTalk_4201_Chest"
  },
  PhantomTalk_4202_Chest = {
    ContentEN = "Treasure? Nice. Think they'll let me trade it for a day off?",
    ContentJP = "お宝？一日休みと引き換えできたらなあ。",
    ContentKR = "보물? 하루 휴가로 바꿀 수 있으면 좋겠네.",
    ContentTC = "寶貝？能換來一天假期就好啦。",
    TextMapContent = "宝贝？能换来一天假期就好啦。",
    TextMapId = "PhantomTalk_4202_Chest"
  },
  PhantomTalk_4301_Chest = {
    ContentEN = "Treasure, just lying around? Hmph. I've no interest in prey that doesn't resist.",
    ContentJP = "そこらに転がってる宝物？そんな手に入れて当然の獲物なんて、興味ないわ。",
    ContentKR = "흩어진 보물? 손쉽게 얻을 수 있는 사냥감엔 관심 없어.",
    ContentTC = "散落的寶物？我對唾手可得的獵物不感興趣。",
    TextMapContent = "散落的宝物？我对唾手可得的猎物不感兴趣。",
    TextMapId = "PhantomTalk_4301_Chest"
  },
  PhantomTalk_5101_Chest = {
    ContentEN = "You found something, Filbert? Wait—this isn't food! Spit it out!",
    ContentJP = "ヘーゼルナッツ、何かいいもの見つかった？ちょっと待って、それは食べちゃダメ！",
    ContentKR = "헤이즐넛이 좋은 걸 찾았다고? 잠깐, 이건 먹으면 안 돼!",
    ContentTC = "榛子找到什麼好東西啦？等一等，這個不能吃哦！",
