  },
  PhantomTalk_5102_Chest = {
    ContentEN = "Look what I found! Let's split it 50-50, as always.",
    ContentJP = "見てみろよ、何を見つけたと思う？いつものルールで、半分こな？",
    ContentKR = "내가 뭘 찾았는지 봐. 늘 하던 대로 반반씩 나눌까?",
    ContentTC = "看看我找到了什麼，老規矩，一人一半？",
