  RESOURCE_DESC_10203 = {
    ContentEN = "Only through silence and self-exploration can one achieve growth from the inside out.",
    ContentJP = "沈黙を守る、己の潜在能力を見出す、そうすればこそ本当の成長になれる。",
    ContentKR = "침묵을 지키고, 진정한 자신을 찾아야, 내면에서 비롯된 성장을 얻을 수 있다.",
    ContentTC = "保持緘默，探尋自我，才能獲得由內至外的成長。",
    TextMapContent = "保持缄默，探寻自我，才能获得由内至外的成长。",
    TextMapId = "RESOURCE_DESC_10203"
  },
  RESOURCE_DESC_10204 = {
    ContentEN = "Only through silence and self-exploration can one achieve growth from the inside out.",
    ContentJP = "沈黙を守る、己の潜在能力を見出す、そうすればこそ本当の成長になれる。",
    ContentKR = "침묵을 지키고, 진정한 자신을 찾아야, 내면에서 비롯된 성장을 얻을 수 있다.",
    ContentTC = "保持緘默，探尋自我，才能獲得由內至外的成長。",
    TextMapContent = "拓宽视野，探寻自我，才能获得由内至外的成长。",
    TextMapId = "RESOURCE_DESC_10204"
  },
  RESOURCE_DESC_10205 = {
    ContentEN = "Only through silence and self-exploration can one achieve growth from the inside out.",
    ContentJP = "沈黙を守る、己の潜在能力を見出す、そうすればこそ本当の成長になれる。",
    ContentKR = "침묵을 지키고, 진정한 자신을 찾아야, 내면에서 비롯된 성장을 얻을 수 있다.",
