  RESOURCE_DESC_103 = {
    ContentEN = "Taking on Commissions consumes Sanergy.",
    ContentJP = "依頼を実行するにはスタミナを消耗する。",
    ContentKR = "의뢰를 수행할 때 필요한 에너지.",
    ContentTC = "集中精力，完成委託，精疲力盡之時，記得適當休息。",
    TextMapContent = "完成各项委托需要消耗的精力。",
    TextMapId = "RESOURCE_DESC_103"
  },
  RESOURCE_DESC_105 = {
    ContentEN = "A rare currency that can be exchanged for various rewards. Only usable during the Second Closed Beta Test.",
    ContentJP = "さまざまな報酬と交換できる貴重な通貨、第2回クローズドβテスト期間中のみ使用可能。",
    ContentKR = "다양한 보상으로 교환 가능한 귀중한 화폐, 2차 클로즈 베타 테스트에서만 사용 가능합니다.",
    ContentTC = "可兌換多種獎勵的珍貴貨幣，僅限致明日測試使用。",
    TextMapContent = "可兑换多种奖励的珍贵货币，仅限致明日测试使用。",
    TextMapId = "RESOURCE_DESC_105"
  },
  RESOURCE_DESC_110 = {
    ContentEN = "The kaleidoscope, casting a prismatic profusion of light — a sliver, caught by eyes in the darkness, unfolds countless worlds in motion.",
    ContentJP = "虹色に反射するプリズム。暗闇のなかで目が捉えたひと筋から、無数の世界が回り出す。",
    ContentKR = "찬란한 광채를 반사하는 프리즘. 어두운 밤, 두 눈이 한 줄기 빛의 흔적을 포착하자, 세계라는 이름의 만화경이 회전하기 시작한다.",
    ContentTC = "可以反射出斑斕萬華的稜鏡。一痕光被黑夜中的雙眼捕捉，世界為名的萬花筒就此旋轉。",
    TextMapContent = "可以反射出斑斓万华的棱镜。一痕光被黑夜中的双眼捕捉，世界为名的万花筒就此旋转。",
    TextMapId = "RESOURCE_DESC_110"
  },
  RESOURCE_DESC_11001 = {
    ContentEN = "Crafted with precision from the blueprint of a basic weapon component. As the part closest to the wielder, the essence of its design is to ensure optimal \"handiness.\"",
    ContentJP = "設計図に基づき製造された初級武器のパーツ。使用者が一番よく触れる部分で、「使いやすさ」を最優先に設計されている。",
    ContentKR = "도면대로 정확히 제작한 초급 무기 부품. 사용자의 편의성을 위해 실질적인 설계 목적을 갖고 만들어졌다.",
    ContentTC = "嚴格按照圖紙打造的初級武器部件。冷兵器上最貼近使用者的部分，「趁手」，是它最實際的設計目的。",
    TextMapContent = "严格按照图纸打造的初级武器部件。冷兵器上最贴近使用者的部分，“趁手”，是它最实际的设计目的。",
    TextMapId = "RESOURCE_DESC_11001"
  },
  RESOURCE_DESC_11002 = {
    ContentEN = "Crafted with precision from the blueprint of an intermediate weapon component. As the part closest to the wielder, the essence of its design is to ensure optimal \"handiness.\"",
    ContentJP = "設計図に基づき製造された中級武器のパーツ。使用者が一番よく触れる部分で、「使いやすさ」を最優先に設計されている。",
    ContentKR = "도면대로 정확히 제작한 중급 무기 부품. 사용자의 편의성을 위해 실질적인 설계 목적을 갖고 만들어졌다.",
    ContentTC = "嚴格按照圖紙打造的中級武器部件。冷兵器上最貼近使用者的部分，「趁手」，是它最實際的設計目的。",
    TextMapContent = "严格按照图纸打造的中级武器部件。冷兵器上最贴近使用者的部分，“趁手”，是它最实际的设计目的。",
    TextMapId = "RESOURCE_DESC_11002"
  },
  RESOURCE_DESC_11003 = {
    ContentEN = "Crafted with precision from the blueprint of an advanced weapon component. As the part closest to the wielder, the essence of its design is to ensure optimal \"handiness.\"",
    ContentJP = "設計図に基づき製造された上級武器のパーツ。使用者が一番よく触れる部分で、「使いやすさ」を最優先に設計されている。",
    ContentKR = "도면대로 정확히 제작한 고급 무기 부품. 사용자의 편의성을 위해 실질적인 설계 목적을 갖고 만들어졌다.",
    ContentTC = "嚴格按照圖紙打造的高級武器部件。冷兵器上最貼近使用者的部分，「趁手」，是它最實際的設計目的。",
    TextMapContent = "严格按照图纸打造的高级武器部件。冷兵器上最贴近使用者的部分，“趁手”，是它最实际的设计目的。",
    TextMapId = "RESOURCE_DESC_11003"
  },
  RESOURCE_DESC_11004 = {
    ContentEN = "Crafted with precision from the blueprint of a basic weapon component. Whether the blade is curved or straight, light or heavy, its edge is honed exclusively for battle.",
    ContentJP = "設計図に基づき製造された初級武器のパーツ。まっすぐであろうと、弧を描いていようと、重かろうが軽かろうが、すべての鋭い刃は戦いのために生まれた。",
    ContentKR = "도면대로 정확히 제작한 초급 무기 부품. 칼날의 휘어진 정도나 무게는 신경 쓰지 않고, 전투를 위한 서슬 퍼런 칼날을 만들었다.",
    ContentTC = "嚴格按照圖紙打造的初級武器部件。無論刀刃是曲是直，是輕是重，它的鋒芒都只為戰鬥而生。",
    TextMapContent = "严格按照图纸打造的初级武器部件。无论刀刃是曲是直，是轻是重，它的锋芒都只为战斗而生。",
    TextMapId = "RESOURCE_DESC_11004"
  },
  RESOURCE_DESC_11005 = {
    ContentEN = "Crafted with precision from the blueprint of an intermediate weapon component. Whether the blade is curved or straight, light or heavy, its edge is honed exclusively for battle.",
    ContentJP = "設計図に基づき製造された中級武器のパーツ。まっすぐであろうと、弧を描いていようと、重かろうが軽かろうが、すべての鋭い刃は戦いのために生まれた。",
    ContentKR = "도면대로 정확히 제작한 중급 무기 부품. 칼날의 휘어진 정도나 무게는 신경 쓰지 않고, 전투를 위한 서슬 퍼런 칼날을 만들었다.",
    ContentTC = "嚴格按照圖紙打造的中級武器部件。無論刀刃是曲是直，是輕是重，它的鋒芒都只為戰鬥而生。",
    TextMapContent = "严格按照图纸打造的中级武器部件。无论刀刃是曲是直，是轻是重，它的锋芒都只为战斗而生。",
    TextMapId = "RESOURCE_DESC_11005"
  },
  RESOURCE_DESC_11006 = {
    ContentEN = "Crafted with precision from the blueprint of an advanced weapon component. Whether the blade is curved or straight, light or heavy, its edge is honed exclusively for battle.",
    ContentJP = "設計図に基づき製造された上級武器のパーツ。まっすぐであろうと、弧を描いていようと、重かろうが軽かろうが、すべての鋭い刃は戦いのために生まれた。",
    ContentKR = "도면대로 정확히 제작한 고급 무기 부품. 칼날의 휘어진 정도나 무게는 신경 쓰지 않고, 전투를 위한 서슬 퍼런 칼날을 만들었다.",
    ContentTC = "嚴格按照圖紙打造的高級武器部件。無論刀刃是曲是直，是輕是重，它的鋒芒都只為戰鬥而生。",
    TextMapContent = "严格按照图纸打造的高级武器部件。无论刀刃是曲是直，是轻是重，它的锋芒都只为战斗而生。",
    TextMapId = "RESOURCE_DESC_11006"
  },
  RESOURCE_DESC_11007 = {
    ContentEN = "Crafted with precision from the blueprint of a basic weapon component. It embodies the wielder's will — only the strong are entitled to showcase their unique individuality on the battlefield.",
