  RESOURCE_DESC_12028 = {
    ContentEN = "Crafted with precision from the blueprint of Entropic Singularity. There is no turning back once the trigger is pulled, much like the commitment that seals a decisive moment.",
    ContentJP = "設計図に基づき製造された「エントロピーゼロ」のパーツ引き金を引けばもう後戻りはできない。――決意を下す瞬間のように。",
    ContentKR = "도면대로 정확히 제작한 무질서의 특이점 부품. 일단 방아쇠를 당기면, 마치 결심을 내린 그 순간처럼 탄환은 절대 뒤를 돌아보지 않는다.",
    ContentTC = "嚴格按照圖紙打造的無序奇點部件。一旦扣下扳機，子彈就不會回頭——就如同人下定決心的那一瞬。",
    TextMapContent = "严格按照图纸打造的无序奇点部件。一旦扣下扳机，子弹就不会回头——就如同人下定决心的那一瞬。",
    TextMapId = "RESOURCE_DESC_12028"
  },
  RESOURCE_DESC_12029 = {
    ContentEN = "Crafted with precision from the blueprint of Entropic Singularity. Sturdy and robust, it doubles effectively as a blunt instrument or a throwable weapon when out of bullets.",
