  RESOURCE_DESC_19008 = {
    ContentEN = "Where threads of the heart entwine, a Soulprint takes form — Longing.",
    ContentJP = "心の跡がここに集まり、渇望となる。",
    ContentKR = "마음의 흔적이 이곳에 모이니, 갈망이 된다.",
