  RESOURCE_DESC_41009 = {
    ContentEN = "Habitual gestures often reveal what lies beneath the mind.",
    ContentJP = "習慣的な所作こそ、人の深層意識の写し鏡であることが多い。",
    ContentKR = "무심코 반복하는 행동이야말로, 사람의 가장 깊은 내면을 비추는 거울이다.",
    ContentTC = "習慣性的動作，往往才是人們深層意識的寫照。",
    TextMapContent = "习惯性的动作，往往才是人们深层意识的写照。",
    TextMapId = "RESOURCE_DESC_41009"
  },
  RESOURCE_DESC_41010 = {
    ContentEN = "No traveller can resist a chest found along the road.",
    ContentJP = "道すがら見つけた宝箱に抗える者などいない。",
    ContentKR = "길에 놓인 보물 상자를 마다할 사람은 없겠지.",
    ContentTC = "沒有人可以抗拒路上碰到的寶箱。",
    TextMapContent = "没有人可以抗拒路上碰到的宝箱。",
    TextMapId = "RESOURCE_DESC_41010"
  },
  RESOURCE_DESC_41011 = {
    ContentEN = "Help! The bed refuses to let me go.",
    ContentJP = "助けて、ベッドに捕まった。",
    ContentKR = "으악, 침대에게 붙잡혔다.",
    ContentTC = "救命，我被床抓住了。",
    TextMapContent = "救命，我被床抓住了。",
    TextMapId = "RESOURCE_DESC_41011"
  },
  RESOURCE_DESC_41012 = {
    ContentEN = "A melody of midsummer and violets, plays upon the strings.",
    ContentJP = "真夏と三色スミレをめぐる詩篇を一曲奏でよう。",
    ContentKR = "한여름 밤과 제비꽃에 관련된 시를 연주한다.",
    ContentTC = "演奏一首關於仲夏與三色堇的詩篇。",
    TextMapContent = "演奏一首关于仲夏与三色堇的诗篇。",
    TextMapId = "RESOURCE_DESC_41012"
  },
  RESOURCE_DESC_41013 = {
    ContentEN = "How'd you know I landed a big catch today?",
    ContentJP = "どうして私が今日、大物を釣り上げたって知ってるの？",
    ContentKR = "내가 오늘 월척을 낚은 걸 어떻게 알았지?",
    ContentTC = "你怎麼知道我今天釣到了一條大魚。",
    TextMapContent = "你怎么知道我今天钓到了一条大鱼。",
    TextMapId = "RESOURCE_DESC_41013"
  },
  RESOURCE_DESC_41014 = {
    ContentEN = "After a headlong sprint, savour a moment of stillness.",
    ContentJP = "全速疾走のあと、束の間の静寂を味わう。",
    ContentKR = "숨 가쁜 질주 후, 찰나의 고요를 즐겨라.",
