  RESOURCE_DESC_5110500 = {
    ContentEN = "A fishing rod crafted by Lunosmith, featuring a surface monitor styled after Cinder, her trusty little assistant. When a fish bites, Cinder lights up to signal it — though according to customer feedback, some folks got so mesmerised watching it glow, they ended up going home with an empty bucket.",
    ContentJP = "ルーナ族の鍛冶師が手がけた釣り竿。付属の水面監視者「すみっコ」は、魚がかかった際に鳴き声で合図してくれる。ただし、あまりに愛らしく見入ってしまい、肝心のタイミングを逃す者も少なくないとか。",
    ContentKR = "대장장이 루나가 제작한 낚싯대. 수면 감지 까망이 한 마리가 증정품으로 딸려 온다. 물고기가 바늘을 물면 까망이가 신호를 준다. 구매한 사람들의 평가를 들어보면, 까망이에 정신이 팔려 빈손으로 돌아가는 사람도 많다고 한다.",
    ContentTC = "由鐵匠皎皎出品的魚竿，附贈水面監測者烏烏一隻。烏烏會在魚兒上鉤的時候發出信號，然而據買家反饋，也有人盯著它走神以至於屢次空手而歸。",
    TextMapContent = "由铁匠皎皎出品的鱼竿，附赠水面监测者乌乌一只。乌乌会在鱼儿上钩的时候发出信号，然而据买家反馈，也有人盯着它走神以至于屡次空手而归。",
    TextMapId = "RESOURCE_DESC_5110500"
  },
  RESOURCE_DESC_5210100 = {
    ContentEN = "A standard lure meant to attract a fish's attention — whether it actually helps you catch anything... is another matter entirely.",
    ContentJP = "魚を引き寄せるための一般的なアイテム。ただし、あくまで誘引効果があるだけで、実際に釣れるかどうかは運と腕次第。",
    ContentKR = "일반적인 물고기 덫. 실제로는 미끼 역할만 할 뿐 물고기를 잡을 수 있을지는 아무도 모른다.",
    ContentTC = "普通的魚類誘捕器，但實際上只能起到引誘的作用，能不能真正捕到魚，那是另外一件事。",
    TextMapContent = "普通的鱼类诱捕器，但实际上只能起到引诱的作用，能不能真正捕到鱼，那是另外一件事。",
    TextMapId = "RESOURCE_DESC_5210100"
  },
  RESOURCE_DESC_5210200 = {
    ContentEN = "A special lure that shortens bite time. Maybe it's the way it wriggles — irresistible to most underwater dwellers.",
    ContentJP = "魚が上釣るまでの時間を短縮できる特製餌。水中でひねるようにうねりながら動くため、周囲の魚たちの視線を一身に集める。その奇妙な動きに、水底の住人たちは思わず近づいてしまうようだ。",
    ContentKR = "특별한 미끼. 미끼를 무는 시간이 단축된다. 꿈틀거리는 모습이 물속 주민들의 관심을 끌어서인 듯하다.",
    ContentTC = "特別的魚餌，可以縮短魚類上鉤的時間，也許是因為它在水中扭來扭去的樣子充分吸引了水下居民的注意。",
    TextMapContent = "特别的鱼饵，可以缩短鱼类上钩的时间，也许是因为它在水里扭来扭去的样子充分引起了水下居民的注意。",
    TextMapId = "RESOURCE_DESC_5210200"
  },
  RESOURCE_DESC_5210300 = {
    ContentEN = "A formulated bait that boosts your odds of luring fish variants. To a creature with eccentric tastes, maybe a glinting hunk of scrap can pass for fine cuisine.",
    ContentJP = "変異種の食いつき率を高める特別な餌。見た目はただの金属片だが、その光沢のせいか、変異種の目にはたまらなく魅力的に映るらしい。",
    ContentKR = "특별한 미끼. 변이 어류를 낚을 확률이 증가한다. 특이종 물고기에겐 금속 미끼가 특별해 보이나 보다.",
    ContentTC = "特別的魚餌，可以增加變種魚類上鉤的機率，也許在特別的魚眼中，金屬的魚餌也夠特殊。",
    TextMapContent = "特别的鱼饵，可以增加变异鱼类上钩的概率，也许在特别的鱼眼中，金属的鱼饵也足够特殊。",
    TextMapId = "RESOURCE_DESC_5210300"
  },
  RESOURCE_DESC_5210400 = {
    ContentEN = "A deceptively plain-looking lure, crafted from top-grade ingredients. Even the pickiest of fish keep pecking until the very last crumb is gone.",
    ContentJP = "変異種を釣り上げる確率を高める特別な餌。見た目は地味だが、原材料は一級品。ひとたび味わえば、どんな偏食の魚でも完食せずにはいられない。",
    ContentKR = "특별한 미끼. 희귀 어류를 낚을 확률이 증가한다. 평범해 보이지만 철저히 계산된 설계다. 한입 먹어보면 아무리 입이 까다로운 물고기라도 이 미끼를 끝까지 먹으려 할 거다.",
    ContentTC = "特別的魚餌，可以增加稀有魚類上鉤的機率，看起來平平無奇，實則用料講究。只要嚐過一口，無論是多麼挑嘴的魚都會無法遏制地把它吃完。",
    TextMapContent = "特别的鱼饵，可以增加稀有鱼类上钩的概率，看起来平平无奇，实则用料讲究。只要尝过一口，无论是多么挑嘴的鱼都会无法遏制地把它吃完。",
    TextMapId = "RESOURCE_DESC_5210400"
  },
  RESOURCE_DESC_6000001 = {
    ContentEN = "A trade voucher issued by EverSpring, Zhiliu's guild.",
    ContentJP = "シリュウ傘下の商会「百年春」が発行した信用通貨。",
    ContentKR = "지류 상회 '백년춘'에서 발행한 신용 증서.",
    ContentTC = "止流旗下商會「百年春」發行的信用憑證。",
    TextMapContent = "止流旗下商会「百年春」发行的信用凭证。",
    TextMapId = "RESOURCE_DESC_6000001"
  },
  RESOURCE_DESC_99 = {
    ContentEN = "A crystal harvested from a Heaventree — one of the most widely used minerals across Atlasia.\nIt emits a gentle glow, reminiscent of a full moon's radiance.",
    ContentJP = "天上樹から採取された結晶で、アトラシア大陸では広く利用されている鉱物。\n満月のようなやわらかな輝きを放つことから、この名がついた。",
    ContentKR = "천국의 나무에서 딴 결정체, 아트라시아 대륙에서 광범위하게 사용되는 광물이다.\n보름달처럼 부드러운 빛을 내어 이러한 이름이 붙었다.",
    ContentTC = "自天之樹採擷的晶體，是阿特拉西亞大陸用途廣泛的礦物。\n 因閃耀著滿月般的柔和光輝而得名。",
    TextMapContent = "自天之树采撷的晶体，是阿特拉西亚大陆用途广泛的矿物。\n因闪耀着满月般的柔和光辉而得名。",
    TextMapId = "RESOURCE_DESC_99"
  },
  RESOURCE_DESC_CANCELPHANTOM = {
    ContentEN = [[
A sigil for retracting a summoning. 
Although the gathering is brief, the longing does not cease, and perhaps the next reunion is just a blink away. ]],
    ContentJP = "召喚を撤回するための印。\nつかのまの邂逅だとしても、想いは途絶えない。きっとすぐにまた、再会できる日が来るのだから。",
    ContentKR = "소환 철회에 사용되는 인장. \n짧은 만남일 지라도 인연은 계속된다. 어쩌면 다음 만남은 눈 깜짝할 사이에 이루어질지도 모른다.",
    ContentTC = "用於撤回召喚的印記。\n相聚雖然短暫，思念不會斷絕，也許下一次的重逢，只在眨眼之間。",
    TextMapContent = "用于撤回召唤的印记。\n相聚虽然短暂，思念不会断绝，也许下一次的重逢，只在眨眼之间。",
    TextMapId = "RESOURCE_DESC_CANCELPHANTOM"
  },
  RESOURCE_DESC_GENERALSKIN_1 = {
    ContentEN = "Grants a character skin from: Berenica, Phantasio, Lisbell, Lady Nifle, Fina, Rebecca, Tabethe, Lynn, Yale and Oliver, Hellfire, Margie, Rhythm, Randy, Sibylle, Truffle and Filbert, Outsider, Psyche, or Daphne.",
    ContentJP = "使用するとベレニカ、ファンタジオ、リズベル、ニフル夫人、フィーナ、レベッカ、タビテ、リーン、イェール＆オリバー、ヘルファイア、マギー、リズム、ランディー、シビル、トリュフ&ヘーゼルナッツ、アウトサイダー、サイキ、ダフネの中からキャラクターの外見一式を一つ選択して獲得できます。",
    ContentKR = "사용 시 베레니카, 환상, 리사벨, 나이플 부인, 피나, 레베카, 타비사, 린, 예일과 올리버, 헬파이어, 마르제, 리듬, 랜디, 시빌라, 트러플과 헤이즐넛, 아웃사이더, 프시케, 다프네 캐릭터 코스튬 중 1세트를 선택할 수 있다.",
    ContentTC = "使用後可從貝蕾妮卡，幻景，莉茲貝爾，妮弗爾夫人，菲娜，麗蓓卡，塔比瑟，琳恩，耶爾與奧利弗，海爾法，瑪爾潔，黎瑟，蘭迪，西比爾，松露與榛子，奧特賽德，賽琪，達芙涅中自選一套角色形象。",
    TextMapContent = "使用后可从贝蕾妮卡，幻景，莉兹贝尔，妮弗尔夫人，菲娜，丽蓓卡，塔比瑟，琳恩，耶尔与奥利弗，海尔法，玛尔洁，黎瑟，兰迪，西比尔，松露与榛子，奥特赛德，赛琪，达芙涅中自选一套角色形象。",
    TextMapId = "RESOURCE_DESC_GENERALSKIN_1"
  },
  RESOURCE_DESC_MUSIC = {
    ContentEN = "A piece of sheet music — its notes trace a story like footprints in the sand.",
    ContentJP = "一枚の楽譜――音符が物語と軌跡を記す。",
    ContentKR = "악보 한 장. 음표로 하나의 이야기와 발자취를 기록하고 있다.",
    ContentTC = "一張樂譜，用音符記錄著一個故事，一行足跡。",
    TextMapContent = "一张乐谱，用音符记录着一个故事，一行足迹。",
    TextMapId = "RESOURCE_DESC_MUSIC"
  },
  RESOURCE_DESC_OPTWEAPON_1 = {
    ContentEN = "Grants a weapon of your choice.",
    ContentJP = "使用するとリストから任意の武器を1つ選んで入手できます。",
    ContentKR = "사용 시 목록에서 무기 1개를 선택할 수 있다.",
    ContentTC = "使用後可從列表中自選一把武器。",
    TextMapContent = "使用后可从列表中自选一把武器。",
    TextMapId = "RESOURCE_DESC_OPTWEAPON_1"
  },
  RESOURCE_DESC_PHANTOM = {
    ContentEN = [[
A sigil for summoning Combat Partners. It is a staff to lean on in a battle, a pact of companionship, and an oath unspoken.
Heartfelt prayers shall be answered, and the desired one shall appear by your side.]],
    ContentJP = "戦友を召喚するための印。それは、肩を並べて戦う決意であり、手をとりあって歩む信頼であり、無言の誓いである。\n祈りが思いとなり伝わったとき、望み通りその人は現れるだろう。あなたの傍らに。",
    ContentKR = "동료 소환에 사용되는 인장. 어깨를 나란히 하고 함께 나아가는 신뢰이자 무언의 약속이다. \n기도로 생각을 전달하면 그 사람은 당신이 생각하는 대로 당신의 곁으로 찾아올 것이다.",
    ContentTC = "用於召喚同伴的印記，是並肩作戰的指仗，是攜手同行的信賴，是沉默無言的承諾。\n當祈禱將思念傳遞，那人會如你所想，降臨於你的身邊。",
    TextMapContent = "用于召唤同伴的印记，是并肩作战的指仗，是携手同行的信赖，是沉默无言的承诺。\n当祈祷将思念传递，那人会如你所想，降临于你的身边。",
    TextMapId = "RESOURCE_DESC_PHANTOM"
  },
  RESOURCE_DESC_ROOT = {
    ContentEN = "Thoughts sifted from the drifting sands of remembrance. They carry the memory of someone — from the past, or from what is yet to come.",
    ContentJP = "記憶の流砂から切り取られた想いの欠片。そこには、過去や未来にまつわる、ある人物の記憶が宿っている。",
    ContentKR = "기억의 모래 속에서 건져낸 아이디어 조각. 과거 또는 미래에 있는 어떤 이에 대한 기억이 담겨있다.",
    ContentTC = "由記憶的流沙中擷取的思緒片段，承載著過去或未來的，關於某個人的記憶。",
    TextMapContent = "由记忆的流沙中撷取的思绪片段，承载着过去或未来的，关于某个人的记忆。",
    TextMapId = "RESOURCE_DESC_ROOT"
  },
