  RLBlessingGroup_Desc_1 = {
    ContentEN = "Melee Weapon Enhancements",
    ContentJP = "近接武器強化",
    ContentKR = "근접 무기 강화",
    ContentTC = "近戰武器強化",
    TextMapContent = "近战武器强化",
