  SKILL_20303_DESC = {
    ContentEN = "Skill Range +<H>#1</>.",
    ContentJP = "スキル範囲+<H>#1</>。",
    ContentKR = "스킬 범위+<H>#1</>",
    ContentTC = "技能範圍+<H>#1</>。",
    TextMapContent = "技能范围+<H>#1</>。",
    TextMapId = "SKILL_20303_DESC"
