  SKILL_310101_DESC = {
    ContentEN = "Deals Pyro Damage to enemies in front and inflicts [Laceration].",
    ContentJP = "前方範囲内の敵に火属性ダメージを与え、さらに「裂傷」効果を付加する。",
    ContentKR = "앞 범위 내의 적에게 불 속성 대미지를 입히고 [찢어짐]을 부여한다.",
