  SkinGacha_Des_Normal = {
    ContentEN = "You are guaranteed a Purple- or higher-tier item within every <highlight>10</> Weaves, and a Golden-tier item is guaranteed within <highlight>90</> Weaves. Weave counts for the \"%s\" banner are tracked independently and do not carry over to other Myriad banners.",
    ContentJP = "探求を<highlight>10</>回行うごとに、必ずレジェンド以上のアイテムを獲得できます。また、最大で<highlight>90</>回の探求で必ずエピックレアリティのアイテムを獲得できます。",
    ContentKR = "<highlight>10</>회 탐색할 때마다 보라색 등급 이상의 아이템을 확정적으로 획득하며, 최대 <highlight>90</>회 탐색 내에 금색 등급의 아이템을 확정적으로 획득합니다.",
    ContentTC = "每<highlight>10</>次尋覓必定獲取紫色或紫色以上品質道具，至多<highlight>90</>次尋覓必定獲取金色品質道具。",
    TextMapContent = "每<highlight>10</>次寻觅必定获取紫色或紫色以上品质道具，至多<highlight>90</>次寻觅必定获取金色品质道具。",
    TextMapId = "SkinGacha_Des_Normal"
  },
  SkinGacha_Des_Special = {
    ContentEN = "You are guaranteed a Purple- or higher-tier item within every <highlight>10</> Weaves, and Iridescent Prism ×25 is guaranteed within <highlight>90</> Weaves.",
    ContentJP = "探求を<highlight>10</>回行うごとに、必ずレジェンド以上のアイテムを獲得できます。また、最大で<highlight>90</>回の探求で必ずエピックレアリティのアイテムを獲得できます。",
    ContentKR = "<highlight>10</>회 탐색할 때마다 보라색 등급 이상의 아이템을 확정적으로 획득하며, 최대 <highlight>90</>회 탐색 내에 무지개빛 프리즘*<highlight>25</>개를 확정적으로 획득합니다.",
    ContentTC = "每<highlight>10</>次尋覓必定獲取紫色或紫色以上品質道具，至多<highlight>90</>次尋覓必定獲取虹色稜鏡*<highlight>25</>。",
    TextMapContent = "每<highlight>10</>次寻觅必定获取紫色或紫色以上品质道具，至多<highlight>90</>次寻觅必定获取金色品质道具。",
