  UIGuide_RelayMechanism_1 = {
    ContentEN = "Attacking a <H>Phoxynamo Wheel</> will toggle its activation status. If the <H>Phoxynamo Wheel</> is <H>blue</>, it is <H>active</>. If it appears <H>orange</>, it is <H>inactive</>.",
    ContentJP = "何らかの攻撃が<H>「イコル駆動輪」</>に命中すると、オン‐オフの状態が切り替わります。<H>「イコル駆動輪」</>の色が<H>青色</>の時は装置の電源は<H>オン</>、<H>オレンジ色</>の時は装置の電源は<H>オフ</>になっています。",
    ContentKR = "임의의 공격으로 <H>[회전체]</>를 적중시키면 전원 상태가 바뀝니다. <H>[회전체]</>의 색이 <H>파란색</>이면, <H>켜진 상태</>이며, <H>[회전체]</>의 색이 <H>주황색</>이면, <H>꺼진 상태</>입니다.",
    ContentTC = "使用任意攻擊命中<H>[髓動輪]</>，將會改變其開關狀態。若<H>[髓動輪]</>的顏色為<H>藍色</>，則該裝置為<H>開啟狀態</>；若<H>[髓動輪]</>的顏色為<H>橙色</>，則該裝置為<H>關閉狀態</>。",
    TextMapContent = "使用任意攻击命中<H>[髓动轮]</>，将会改变其开关状态。若<H>[髓动轮]</>的颜色为<H>蓝色</>，则该装置为<H>开启状态</>；若<H>[髓动轮]</>的颜色为<H>橙色</>，则该装置为<H>关闭状态</>。",
    TextMapId = "UIGuide_RelayMechanism_1"
  },
  UIGuide_RelayMechanism_2 = {
    ContentEN = "Some <H>Phoxynamo Wheels</> will <H>automatically revert</> to their <H>original state</> after a set time following a status change.",
    ContentJP = "一部の<H>「イコル駆動輪」</>は命中を受けてオン‐オフの状態が切り替わってから一定時間が経過すると、<H>初期状態</>まで<H>自動的に回復</>します。",
    ContentKR = "일부 <H>[회전체]</>는 적중시켜 전원 상태를 바꾼 후, 일정 시간이 지나면 <H>자동 회복</>하여 <H>초기 상태</>로 돌아갑니다.",
    ContentTC = "部分<H>[髓動輪]</>被命中並改變開關狀態後，會在一定時間後<H>自動恢復</>至<H>初始狀態</>。",
