  UIGuide_Temple_1 = {
    ContentEN = "You can challenge [Avian Spirit Trials] by meditating at the recorded Avian Towers.",
    ContentJP = "記録済みの場所で瞑想すると、霊鳥の試練に入り、特別なステージに挑戦できます。",
    ContentKR = "기록된 지역에서 명상하면 영혼의 새 시련에 진입하고 일련의 특수 도전을 오픈할 수 있습니다.",
    ContentTC = "在已記錄的地點冥想，可進入靈鳥試煉，開啟一系列特殊挑戰。",
    TextMapContent = "在已记录的地点冥想，可进入灵鸟试炼，开启一系列特殊挑战。",
    TextMapId = "UIGuide_Temple_1"
  },
  UIGuide_Temple_2 = {
    ContentEN = "You will receive star-rated rewards after your first successful completion of the Trials. You can replay these Trials to achieve higher ratings and earn better rewards.",
    ContentJP = "霊鳥の試練のステージを初めてクリアすると、星レベルに応じた報酬を獲得できます。何度も挑戦して、より高ランクの報酬を目指しましょう。",
    ContentKR = "영혼의 새 시련 스테이지 첫 클리어 시 클리어 레벨에 상응하는 보상을 획득합니다. 반복 도전하여 더 높은 등급의 보상을 획득할 수 있습니다.",
    ContentTC = "首次通關靈鳥試煉關卡會獲得對應星級的獎勵，可反復挑戰以獲得更高等級的獎勵。",
    TextMapContent = "首次通关灵鸟试炼关卡会获得对应星级的奖励，可反复挑战以获得更高等级的奖励。",
    TextMapId = "UIGuide_Temple_2"
  },
  UIGuide_Temple_3 = {
    ContentEN = "You can challenge [Avian Spirit Trials] by clicking the recorded locations on the map.",
    ContentJP = "マップ画面で記録済みの場所をクリックすると、対応する霊鳥の試練に入ります。",
    ContentKR = "지도 화면에서 기록한 지점을 누르면, 해당 영혼의 새 시련에 바로 입장할 수 있습니다.",
    ContentTC = "在地圖界面點擊已記錄的地點，即可進入其對應的靈鳥試煉。",
    TextMapContent = "在地图界面点击已记录的地点，即可进入其对应的灵鸟试炼。",
    TextMapId = "UIGuide_Temple_3"
  },
