  UIGuide_TrainingGround_1 = {
    ContentEN = "Sandrealm Meditation lets you revisit and battle past enemies in a controlled environment, helping you familiarise yourself with their moves and hone your combat skills.",
    ContentJP = "「砂海の瞑想」では、過去に戦った敵と回想のなかで戦うことができます。敵の戦い方を学んで、自分の腕前を上げましょう。",
    ContentKR = "모래 바다의 명상에서는 이전에 만났던 적들을 회상하며 자유롭게 전투할 수 있습니다. 이를 통해 적의 공격 패턴을 익히고 자신의 스킬을 테스트할 수 있습니다.",
    ContentTC = "在沙海冥想中，可以回憶曾經見過的敵人，並與它們進行自主的戰鬥。可以以此熟悉它們的招式、測試自己的技能。",
    TextMapContent = "在沙海冥想中，可以回忆曾经见过的敌人，并与它们进行自主的战斗。可以以此熟悉它们的招式、测试自己的技能。",
    TextMapId = "UIGuide_TrainingGround_1"
  },
  UIGuide_TrainingGround_2 = {
    ContentEN = "Within the <H>Gritty Vortex</> in Sandrealm Meditation, you'll find combat supplies such as <H>Ammo Supply Chests</>, <H>Sal Volatile</>, and <H>Cognizing Sal Volatile</> to facilitate your combat.",
    ContentJP = "「砂海の瞑想」の<H>砂海の渦</>では、<H>弾薬補給箱</>、<H>気つけ薬</>、<H>興奮剤</>などの戦闘が便利になるアイテムがドロップします。",
    ContentKR = "모래 바다의 명상 속 <H>모래 바다 소용돌이</>에는 <H>탄약 보급 상자</>, <H>스멜링 솔트</>, <H>정신 집중 스멜링 솔트</> 등 전투 보급품이 등장하여 더 효과적인 전투 테스트가 가능합니다.",
    ContentTC = "在沙海冥想的<H>沙海漩渦</>中，會出現<H>彈藥補給箱</>、<H>嗅鹽</>、<H>凝神嗅鹽</>等戰鬥補給，便於更好地進行戰鬥測試。",
    TextMapContent = "在沙海冥想的<H>沙海漩涡</>中，会出现<H>弹药补给箱</>、<H>嗅盐</>、<H>凝神嗅盐</>等战斗补给，便于更好地进行战斗测试。",
    TextMapId = "UIGuide_TrainingGround_2"
  },
  UIGuide_TrainingGround_3_PC = {
    ContentEN = "Access <H>Armoury</> at the <H>top right</> of the screen to swiftly switch characters.",
    ContentJP = "<H>右上</>の<H>キャラクター</>画面でキャラクターを切り替えできます。",
    ContentKR = "<H>우측 상단</>의 <H>정비</> 화면을 열어 테스트하고 싶은 캐릭터로 빠르게 전환할 수 있습니다.",
