  UIGuide_TrialRank_1 = {
    ContentEN = "Earn EXP from character, weapon, Geniemon, and Demon Wedge progression, or by completing quests, to raise your Trial Rank.",
    ContentJP = "キャラクター・武器・ジェネモン・魔の楔を育成し、クエスト達成で経験値を獲得して、冒険レベルを上げましょう。",
    ContentKR = "캐릭터, 무기, 마령, 악마의 쐐기 육성, 퀘스트 완료를 통해 수련 경험치를 획득하고, 수련 레벨을 올릴 수 있습니다.",
    ContentTC = "通過培養角色、武器、魔靈和魔之楔，以及完成任務獲得歷練經驗，從而提升歷練等級。",
    TextMapContent = "通过培养角色、武器、魔灵和魔之楔，以及完成任务获得历练经验，从而提升历练等级。",
    TextMapId = "UIGuide_TrialRank_1"
  },
  UIGuide_TrialRank_2 = {
    ContentEN = "Advancing to higher Trial Ranks grants valuable rewards and powerful buffs.",
    ContentJP = "一定の冒険レベルに到達すると、豪華な報酬と強化効果を獲得できます。",
    ContentKR = "일정 수련 레벨에 도달하면, 풍성한 보상과 버프 효과를 획득할 수 있습니다.",
    ContentTC = "達到一定歷練等級後，可以獲得豐厚的獎勵和增益效果。",
    TextMapContent = "达到一定历练等级后，可以获得丰厚的奖励和增益效果。",
