  UIGuide_WallJump_PC = {
    ContentEN = "When near any wall, <H>repeatedly</> press &Jump& to jump up onto the wall.",
    ContentJP = "壁に密着した状態で&Jump&を<H>連続</>で押すと、壁を登ります。",
