  UIGuide_content_203001 = {
    ContentEN = "While exploring the world, you may come across <H>Geniemons</>. Use <H>Treats</> to become friends with them. Geniemons can empower your team in battle through Geniemon Support.",
    ContentJP = "世界探索の途中で時折<H>ジェネモン</>と出会うことがある。<H>缶詰</>を消費して餌を与えられる。ジェネモンはジェネモン支援を通じて、戦闘でさまざまな助力をしてくれる。",
    ContentKR = "월드 탐사 시 종종 <H>마령</>과 조우할 수 있으며, <H>통조림</>을 소모하여 먹이를 줄 수 있습니다. 마령은 마령 지원을 통해 전투에 다양한 도움을 제공합니다.",
    ContentTC = "世界探索時偶爾會遇到<H>魔靈</>，可消耗<H>罐罐</>投喂它們。魔靈可以通過魔靈支援，在戰鬥中提供多種助力。",
    TextMapContent = "世界探索时偶尔会遇到<H>魔灵</>，可消耗<H>罐罐</>投喂它们。魔灵可以通过魔灵支援，在战斗中提供多种助力。",
    TextMapId = "UIGuide_content_203001"
  },
  UIGuide_content_203501 = {
    ContentEN = "In towns and other <H>safe areas</>, <H>hold</> &Skill3& to switch to the protagonist for exploration and interaction.",
    ContentJP = "街などの<H>安全エリア</>では、<H>&Skill3&長押し</>で主人公の切り替えができます。",
    ContentKR = "마을 등의 <H>안전 구역</>에서 &Skill3& 버튼을 <H>길게 눌러</> 주인공으로 전환한 뒤 플레이 및 탐색할 수 있습니다.",
    ContentTC = "在城鎮等<H>安全區域</>，可<H>長按</>&Skill3&切換出主角進行體驗和探索。",
    TextMapContent = "在城镇等<H>安全区域</>，可<H>长按</>&Skill3&切换出主角进行体验和探索。",
    TextMapId = "UIGuide_content_203501"
  },
  UIGuide_content_203601 = {
    ContentEN = "You can challenge [Avian Spirit Trials] by meditating at the recorded Avian Towers.",
    ContentJP = "記録済みの場所で瞑想すると、霊鳥の試練に入り、特別なステージに挑戦できます。",
    ContentKR = "기록된 지역에서 명상하면 영혼의 새 시련에 진입하고 일련의 특수 도전을 오픈할 수 있습니다.",
    ContentTC = "在已記錄的地點冥想，可進入靈鳥試煉，開啟一系列特殊挑戰。",
    TextMapContent = "在已记录的地点冥想，可进入灵鸟试炼，开启一系列特殊挑战。",
    TextMapId = "UIGuide_content_203601"
  },
  UIGuide_content_203602 = {
    ContentEN = "Receive star-rated rewards after your first successful completion of the Trials. You can replay these trials to achieve higher ratings and earn better rewards.",
    ContentJP = "霊鳥の試練のステージを初めてクリアすると、星レベルに応じた報酬を獲得できます。何度も挑戦して、より高ランクの報酬を目指しましょう。",
    ContentKR = "영혼의 새 시련 스테이지 첫 클리어 시 클리어 등급에 상응하는 보상을 획득합니다. 반복 도전하여 더 높은 등급의 보상을 획득할 수 있습니다.",
    ContentTC = "首次通關靈鳥試煉關卡會獲得對應星級的獎勵，可反復挑戰以獲得更高等級的獎勵。",
    TextMapContent = "首次通关灵鸟试炼关卡会获得对应星级的奖励，可反复挑战以获得更高等级的奖励。",
    TextMapId = "UIGuide_content_203602"
  },
