  },
  UI_Achievement_Des_70136 = {
    ContentEN = "\"I'll never let anyone die to Filthoids again.\"",
    ContentJP = "「もう二度と、穢獣に殺される人を見過ごしたりしない。」",
    ContentKR = "\"더는 필토이드가 사람을 해치는 걸 지켜보지 않겠어.\"",
    ContentTC = "「我不會再看著任何人被穢獸殺死。」",
    TextMapContent = "“我不会再看着任何人被秽兽杀死。”",
    TextMapId = "UI_Achievement_Des_70136"
  },
  UI_Achievement_Des_70137 = {
    ContentEN = "Land a big fish for the residents of Mist Aken.",
    ContentJP = "霧の街の住民のためにヌシを釣り上げることに成功した。",
    ContentKR = "안개 구역 주민들을 위해 대어 낚기",
    ContentTC = "成功為霧區居民釣上大魚。",
    TextMapContent = "成功为雾区居民钓上大鱼。",
    TextMapId = "UI_Achievement_Des_70137"
  },
  UI_Achievement_Des_70138 = {
    ContentEN = "We are all in the gutter, but some of us are looking at the stars.",
    ContentJP = "我らは溝の中に生きる――それでも、星空を仰ぎ見る者がいる。",
    ContentKR = "우리는 진창 속에서 살고 있지만, 여전히 누군가는 별하늘을 바라본다.",
    ContentTC = "我們生活在溝渠裡，但仍有人仰望星空。",
    TextMapContent = "我们生活在沟渠里，但仍有人仰望星空。",
    TextMapId = "UI_Achievement_Des_70138"
  },
  UI_Achievement_Des_70139 = {
    ContentEN = "I pictured our reunion countless times — but never like this.",
    ContentJP = "私は幾度となく再会を思い描いた、ただし決してこんな形ではなかった。",
    ContentKR = "우리의 재회를 수없이 그려봤지만, 이런 방식은 절대 아니었다.",
    ContentTC = "我設想過很多次我們的重逢，但唯獨不是以這種方式。",
    TextMapContent = "我设想过很多次我们的重逢，但唯独不是以这种方式。",
    TextMapId = "UI_Achievement_Des_70139"
  },
  UI_Achievement_Des_70140 = {
    ContentEN = "Tear the cage apart — even if it leaves your hands in tatters.",
    ContentJP = "囚われの檻を打ち砕け、たとえ残されたのが傷だらけの手だけでも。",
    ContentKR = "감옥을 찢어발겨라, 완전하지 않은 손바닥만 남았을지언정.",
    ContentTC = "撕碎囚籠吧，縱使只剩殘損的手掌。",
    TextMapContent = "撕碎囚笼吧，纵使只剩残损的手掌。",
    TextMapId = "UI_Achievement_Des_70140"
  },
  UI_Achievement_Des_70141 = {
    ContentEN = "\"To the only successful performance of my life.\"",
    ContentJP = "「生涯唯一の成功した演目に寄せて。」",
    ContentKR = "\"내 인생에 단 한 번뿐인 성공적인 공연을 위하여.\"",
    ContentTC = "「致我生命中僅此一次的成功演出。」",
