  UI_HardBoss_Des_1 = {
    ContentEN = "The chief of the Hyperborean Empire's 13th Legion. Her arrival on Purgatorio Island irrevocably altered our destiny.",
    ContentJP = "ヒュペリア帝国軍第十三軍団の軍団長。彼女がパーガトリー島に現れたあの日、私たちの運命は動きだし、あの頃の日常は永遠に失われた。",
    ContentKR = "휘페르보레아 제국 제13군단 군단장. 그날 연옥도에서 그녀와 마주친 뒤로, 우리의 운명은 원래의 궤적에서 벗어나기 시작했다.",
    ContentTC = "海伯利亞帝國第十三軍團軍團長。那一日在淨界島，她的出現，讓我們的命運永遠地偏離了曾經的軌道。",
    TextMapContent = "海伯利亚帝国第十三军团军团长。那一日在净界岛，她的出现，让我们的命运永远地偏离了曾经的轨道。",
    TextMapId = "UI_HardBoss_Des_1"
  },
  UI_HardBoss_Des_2 = {
    ContentEN = "The Grim Reaper of Glevum. A massive Filthoid in the depths of Glevum Pit, mechanically repeating the behaviour of tunnelling and devouring any glowing objects.",
    ContentJP = "グルビュームの死神。\nグルビューム鉱山の奥に現れる巨大な穢獣。絶えず通路を掘り進み、光るものを呑み込む。",
    ContentKR = "글로스터의 사신. 글로스터 광갱 깊숙한 곳에 나타나는 거대 필토이드. 통로를 파면서 빛나는 물체를 집어삼키는 행위를 반복한다.",
    ContentTC = "格雷姆的死神。出現在格雷姆礦坑深處的巨大穢獸，機械性地重複著挖掘通道與吞噬發光物的行為。",
    TextMapContent = "格雷姆的死神。出现在格雷姆矿坑深处的巨大秽兽，机械性地重复着挖掘通道与吞噬发光物的行为。",
    TextMapId = "UI_HardBoss_Des_2"
  },
  UI_HardBoss_Des_3 = {
    ContentEN = "The seed in the frozen soil that has forfeited the opportunity for a gentle descent into the night.",
    ContentJP = "凍土の種は、夜のとばりへと安らかに羽ばたく機会を逃してしまった。",
    ContentKR = "얼어붙은 땅 속의 씨앗은 부드럽게 밤으로 들어갈 시기를 놓쳤다. ",
    ContentTC = "凍土中的種子，錯過了溫和地走入夜幕的契機。",
    TextMapContent = "冻土中的种子，错过了温和地走入夜幕的契机。",
    TextMapId = "UI_HardBoss_Des_3"
  },
  UI_HardBoss_Des_4 = {
    ContentEN = "The Warden of the Imperial Military Prison wields her chains to chastise evil and her flames to defend justice.",
    ContentJP = "皇立軍事監獄の典獄。彼女の鎖が罪を裁き、彼女の炎が正義を貫く。",
    ContentKR = "황실 군교도소 교도소장. 그녀의 사슬은 죄악을 징벌하고, 그녀의 화염은 정의를 수호한다.",
    ContentTC = "帝國皇家軍監獄典獄長，她的鐵鏈將會懲戒罪惡，她的火焰將會堅守正義。",
    TextMapContent = "帝国皇家军监狱典狱长，她的锁链将会惩戒罪恶，她的火焰将会坚守正义。",
    TextMapId = "UI_HardBoss_Des_4"
  },
  UI_HardBoss_Des_5 = {
    ContentEN = "It is the Beast From the Snowfield, crushing children's homes and melting remnants of the fairy's slumber.",
    ContentJP = "雪国で荒ぶる獣は子供たちの故郷を滅ぼし、妖精たちの夢まで散らす。",
    ContentKR = "설국에서 기승을 부리는 야수. 아이들의 고향을 무너뜨리고, 요정의 깨진 꿈을 녹였다.",
    ContentTC = "那是肆虐在雪國的野獸，摧毀了孩子們的故鄉，融化了妖精的碎夢。",
    TextMapContent = "那是肆虐在雪国的野兽，摧毁了孩子们的故乡，融化了妖精的碎梦。",
    TextMapId = "UI_HardBoss_Des_5"
  },
