    ContentJP = "ナイトソード",
    ContentKR = "기사 한손검",
    ContentTC = "騎士單手劍",
    TextMapContent = "骑士单手剑",
    TextMapId = "UI_WEAPON_NAME_10198"
  },
  UI_WEAPON_NAME_10199 = {
