  UI_WeaponAccessory_Desc_10005 = {
    ContentEN = "A butterfly laid to rest its dream of flight.",
    ContentJP = "羽ばたくことを忘れた蝶は、ただ静かに夢を終えた。",
    ContentKR = "나비는 비행의 꿈을 잃었다.",
    ContentTC = "蝴蝶了卻了飛翔的故夢。",
    TextMapContent = "蝴蝶了却了飞翔的故梦。",
