  UI_WeaponSkin_Des_3010101 = {
    ContentEN = "A true angler never comes home empty-handed. Good thing the fish market had a clearance sale — 80 coins a pop, but no one has to know.",
    ContentJP = "一日釣りをするくらいなら、せめて魚の一匹ぐらい持って帰れ。……ちょうど今日、市場で割引中だ。80銅貨だよ。",
    ContentKR = "하루 종일 낚시를 한 용사는 결코 빈손으로 집에 돌아갈 수 없다. 다행히도 오늘 수산시장에서 할인가 80쿠퍼에 한 마리를 팔고 있다.",
    ContentTC = "釣了一天魚的勇者絕不能空手回家，好在今天魚市降價，80銅幣一條。",
    TextMapContent = "钓了一天鱼的勇者绝不能空手回家，好在今天鱼市降价，80铜币一条。",
    TextMapId = "UI_WeaponSkin_Des_3010101"
  },
  UI_WeaponSkin_Des_3010102 = {
    ContentEN = "Just before they collided, the stars kissed farewell. Their shattered whispers became streaks of fire — lovers' breath adrift across the Milky Way.",
    ContentJP = "星が星と衝突する、その刹那に交わされた別れの口づけ。砕けた囁きは空の彼方へと尾を引き、愚直な抱擁は――まるで銀河が吐息を漏らしたかのようだった。",
    ContentKR = "별들은 충돌하기 전에 작별 인사를 나눈다. 조각난 속삭임은 하늘 위의 불꽃이 되어, 마치 은하가 숨을 내뱉는 것처럼 보인다.",
    ContentTC = "群星與群星在相撞的前一刻吻別，粉碎的呢喃化作天外的尾焰，癡心的相擁恍若銀河的吐息。",
    TextMapContent = "群星与群星在相撞的前一刻吻别，粉碎的呢喃化作天外的尾焰，痴心的相拥恍若银河的吐息。",
    TextMapId = "UI_WeaponSkin_Des_3010102"
  },
  UI_WeaponSkin_Des_3010201 = {
    ContentEN = "Frozen Frostline Trout — firm, flavour-rich, and shelf-stable. Outlasts canned meat, cling wrap, and maybe even your survival instincts.",
    ContentJP = "冷凍保存された戦闘力と旨味。缶詰が腐っても、この魚は腐らない。",
    ContentKR = "냉동 시 힘과 풍미가 함께 깃드는 설무늬어. 통조림과 랩의 유통기한이 지나더라도 이건 멀쩡할 것이다.",
    ContentTC = "適用於單手劍。\n冷凍後兼具力量和味道的雪紋魚，重點是──就算肉罐頭和保鮮紙會過期，它也不會過期。",
    TextMapContent = "冷冻后兼具力量和味道的雪纹鱼，重点是——就算肉罐头和保鲜纸会过期，它也不会过期。",
    TextMapId = "UI_WeaponSkin_Des_3010201"
  },
  UI_WeaponSkin_Des_3010202 = {
    ContentEN = "A sword of unusual design, said to embody a father's love: firm, instructive, and just a little traumatising.",
    ContentJP = "とある父の叱咤が刃となった。愛という名の鞭だ――いや、つまりは、父の愛は重いってことだ。",
    ContentKR = "다소 특이한 검. 아버지의 채찍… 아니, 아버지의 사랑을 상징한다.",
    ContentTC = "一柄頗為特殊的劍，象徵著父親的鞭策──呃，我的意思是說，父愛如山。",
    TextMapContent = "一柄颇为特殊的剑，象征着父亲的鞭策——呃，我的意思是说，父爱如山。",
    TextMapId = "UI_WeaponSkin_Des_3010202"
  },
  UI_WeaponSkin_Des_3010301 = {
    ContentEN = "Where is the sun? Look — it's dancing in the palm of my hand.",
    ContentJP = "お日さまはどこに？お日さまはどこに？お日さまは、私たちの手のひらの中に。",
    ContentKR = "태양아, 태양아 어디에 있니? 태양은 우리의 손안에 있어.",
    ContentTC = "太陽在哪裡呀太陽在哪裡？太陽就在我們的手心裡。",
    TextMapContent = "太阳在哪里呀太阳在哪里？太阳就在我们的手心里。",
    TextMapId = "UI_WeaponSkin_Des_3010301"
  },
  UI_WeaponSkin_Des_3010401 = {
    ContentEN = "A single note breaks the hush — waking her from a midsummer dream, and plucking softly at the strings of her heart.",
    ContentJP = "ひとすじの澄んだ音色が、少女の浅い夢を覚まし、夏の日の心の弦をそっと奏でた。",
    ContentKR = "청아한 목소리가 소녀의 얕은 꿈을 깨우고, 여름의 심금을 울린다.",
    ContentTC = "一抹清音，驚醒了少女的淺夢，撥動了夏日的心弦。",
    TextMapContent = "一抹清音，惊醒了少女的浅梦，拨动了夏日的心弦。",
    TextMapId = "UI_WeaponSkin_Des_3010401"
  },
  UI_WeaponSkin_Des_3010402 = {
    ContentEN = "Waves leap beneath the dancer's steps — summer's rhythm crashing through the air. Here, the rhapsody crests: wild and bright.",
    ContentJP = "波しぶきが舞姫のつま先で跳ね、海風が真夏のすべてを運び、クライマックスがこの瞬間に刻まれる。",
    ContentKR = "물결은 춤추는 자의 발끝에서 넘실대고, 바닷바람은 온 여름의 정수를 감싸며 클라이맥스를 이곳에 새긴다.",
    ContentTC = "浪花在舞者的足尖躍動，海風裹挾著一整個盛夏，將高潮在此定格。",
    TextMapContent = "浪花在舞者的足尖跃动，海风裹挟着一整个盛夏，将高潮在此定格。",
    TextMapId = "UI_WeaponSkin_Des_3010402"
  },
