  },
  voice_ch_char_Aote_vo_topic_05_3 = {
    ContentEN = "...You're milking it, buddy.",
    ContentJP = "……友人としてお前のことを心配してんだぞ！何を図々しく調子に乗ってんだ",
    ContentKR = "...친구로서 걱정해서 한 말인데, 이런 걸로 장난치지 말라고!",
    ContentTC = "……我這是身為朋友在關心你，你別得寸進尺耍無賴啊！",
    TextMapContent = "……我这是身为朋友在关心你，你别得寸进尺耍无赖啊！",
    TextMapId = "voice_ch_char_Aote_vo_topic_05_3"
  },
  voice_ch_char_Aote_vo_victory = {
    ContentEN = "Leave 'em all to me. I'll see if I can find any salvageable bits and bobs lying around.",
    ContentJP = "後は俺が片付けておく、そっちは回収できるものがないか探してな。",
    ContentKR = "조금 있다 청소하러 올게. 떨어진 물건이 있나 확인도 하고.",
