  voice_ch_char_Dafu_vo_skill02_r01 = {
    ContentEN = "How much longer must the flames of war demand our blood?",
    ContentJP = "戦争は、いつまで続くの……",
    ContentKR = "전쟁이여, 언제까지 피를 흘리게 할 건가요?",
