  },
  voice_ch_char_Dafu_vo_skill02_r02 = {
    ContentEN = "I will maintain the utmost respect for human life.",
    ContentJP = "命は宿ったその瞬間から、世で最も尊く眩いものなのです。",
    ContentKR = "생명을 수태된 때로부터 지상의 것으로 존중히 여기겠노라.",
    ContentTC = "生命從孕育之初，即為至高的尊嚴。",
