  voice_ch_char_Dafu_vo_skill02_r03 = {
    ContentEN = "For the peace that will come one day.",
    ContentJP = "いつか訪れる平和のために。",
    ContentKR = "곧 다가올 평화를 위해.",
    ContentTC = "為了終將到來的和平。",
    TextMapContent = "为了终将到来的和平。",
    TextMapId = "voice_ch_char_Dafu_vo_skill02_r03"
