  voice_ch_char_Lise_vo_skill02_r01 = {
    ContentEN = "Mission wrapping up.",
    ContentJP = "まもなく任務完了。",
    ContentKR = "임무는 곧 완료됩니다.",
    ContentTC = "任務即將完成。",
    TextMapContent = "任务即将完成。",
