  voice_ch_char_Maer_vo_gain_2 = {
    ContentEN = "What? You've already heard of my title \"Princess Rubbish Bin\"?! Ugh... please don't go along with it! Just call me Margie. No princess here, just a little scavenger of Icelake!",
