  voice_ch_char_Songlu_vo_gain = {
    ContentEN = "Hellooo! It's me, the Commissary, Truffle, with my faithful followers by my side, Filbert and her family. That's it for my self-introduction - but I gotta say - your eyes look as big as saucers! You must be starving!",
    ContentJP = "ハロハロ～、食糧補給官のトリュフだよっ！そして、こちらは私の可愛い部下たち、ヘーゼルナッツ一家。さて、これで自己紹介はおしまい！ん？あれれ、なんかきょとんとしてますね。もしかして、お腹すいてる？",
    ContentKR = "하이하이, 난 식량보급원 트러플이라고 해. 얘들은 내 든든하고 사랑스러운 부하 헤이즐넛 가족이야. 자기소개 끝! 눈을 왜 이렇게 크게 떴어? 혹시 배고파?",
    ContentTC = "你好你好，我是糧秣專員松露，她們是我的可靠可愛可信賴的部下榛子一家。好，自我介紹結束！看你眼睛瞪這麼大，是不是沒吃飽呀！",
    TextMapContent = "你好你好，我是粮秣专员松露，她们是我的可靠可爱可信赖的部下榛子一家。好，自我介绍结束！看你眼睛瞪这么大，是不是没吃饱呀！",
    TextMapId = "voice_ch_char_Songlu_vo_gain"
  },
  voice_ch_char_Songlu_vo_idle = {
    ContentEN = "Let's take some rest, Filbert. Have some grains and nuts, and a few flowers for snacks. If you're full, I'll pin them to my hat for now.",
    ContentJP = "ヘーゼルナッツ、ひと休みして、小麦とナッツを食べよう。おやつの花も少しある。食べきれなかったら、帽子に挿しとくからね。",
    ContentKR = "좀 쉬자. 헤이즐넛, 밀이랑 견과류 좀 먹어. 간식으로 꽃 몇 송이 더 먹고, 남으면 내 모자 위에 꽂으면 돼.",
    ContentTC = "休息一會兒吧，榛子，吃點小麥，吃點堅果。再來上幾朵花當零食，要是吃不完的話，我就先插在帽子上。",
    TextMapContent = "休息一会儿吧，榛子，吃点小麦，吃点坚果。再来上几朵花当零食，要是吃不完的话，我就先插在帽子上。",
    TextMapId = "voice_ch_char_Songlu_vo_idle"
  },
  voice_ch_char_Songlu_vo_lvup = {
    ContentEN = "An empty tummy won't get you far in battle. So gobble up some grub and prepare to charge towards victory!",
    ContentJP = "強くなるにはいっぱいご飯を食べないと、です。腹が減ってはバトルはできぬ！",
    ContentKR = "배가 불러야 강해지지! 배고프면 싸울 수 없어!",
    ContentTC = "吃飽才能變強，肚子扁扁不能上戰場！",
    TextMapContent = "吃饱才能变强，肚子扁扁不能上战场！",
    TextMapId = "voice_ch_char_Songlu_vo_lvup"
  },
  voice_ch_char_Songlu_vo_revive = {
    ContentEN = "Emergency food is gross... Well, at least it fills up my tummy.",
    ContentJP = "非常食の味は激マズだけど……まぁ、お腹いっぱいになったからヨシ。",
    ContentKR = "비상식량은 맛이 끔찍해... 됐어, 배만 부르면 됐지.",
    ContentTC = "應急食品味道好糟糕……算了，吃飽就行。",
    TextMapContent = "应急食品味道好糟糕……算了，吃饱就行。",
    TextMapId = "voice_ch_char_Songlu_vo_revive"
  },
  voice_ch_char_Songlu_vo_skill01_r01 = {
