  voice_ch_char_Tuosi_vo_gain = {
    ContentEN = "May we meet in the blackest hour of night, where shadows veil my face, sparing you the terror of beholding my true form.",
    ContentJP = "最も夜が深まる刻に会おう。この病に蝕まれた醜い顔が、君を怯えさせぬように。",
    ContentKR = "어둠이 가장 짙을 때 만나자. 그러면 내 진짜 모습 때문에 겁에 질려 소리 지르진 않겠지.",
    ContentTC = "但願我們能在夜色最深沉的時刻相遇，那樣，你便不會因我真實的面容而恐懼得驚叫失聲。",
    TextMapContent = "但愿我们能在夜色最深沉的时刻相遇，那样，你便不会因我真实的面容而恐惧得惊叫失声。",
    TextMapId = "voice_ch_char_Tuosi_vo_gain"
  },
  voice_ch_char_Tuosi_vo_idle = {
    ContentEN = "Hush... I am nearly in character.",
    ContentJP = "静かに……あとちょっとで役に入れそうだから。",
    ContentKR = "쉿... 곧 캐릭터에 몰입할 것 같아.",
    ContentTC = "噓……我就快要進入角色了。",
    TextMapContent = "嘘……我就快要进入角色了。",
    TextMapId = "voice_ch_char_Tuosi_vo_idle"
  },
  voice_ch_char_Tuosi_vo_lvup = {
    ContentEN = "I have rehearsed for such moments countless times in the past.",
    ContentJP = "昔も、こんなふうにリハーサルを繰り返していたものだ。",
    ContentKR = "지난날에도 지금처럼 수없는 리허설을 했었지.",
    ContentTC = "過去，我也曾這樣排練無數次。",
    TextMapContent = "过去，我也曾这样排练无数次。",
    TextMapId = "voice_ch_char_Tuosi_vo_lvup"
  },
  voice_ch_char_Tuosi_vo_revive = {
    ContentEN = "Was that just an intermission?",
    ContentJP = "さっきのは幕間だったのか？",
    ContentKR = "그저 막간이었을 뿐인가?",
    ContentTC = "只是中場休息嗎。",
    TextMapContent = "只是中场休息吗。",
    TextMapId = "voice_ch_char_Tuosi_vo_revive"
  },
  voice_ch_char_Tuosi_vo_skill01_r01 = {
    ContentEN = "Take your bow.",
    ContentJP = "退場の時間だ。",
    ContentKR = "퇴장해라.",
    ContentTC = "退場吧。",
    TextMapContent = "退场吧。",
    TextMapId = "voice_ch_char_Tuosi_vo_skill01_r01"
  },
  voice_ch_char_Tuosi_vo_skill01_r02 = {
    ContentEN = "Silence.",
    ContentJP = "うるさい。",
    ContentKR = "시끄럽다.",
    ContentTC = "太吵了。",
    TextMapContent = "太吵了。",
    TextMapId = "voice_ch_char_Tuosi_vo_skill01_r02"
  },
  voice_ch_char_Tuosi_vo_skill02_r01 = {
    ContentEN = "Even if I am reduced to a beast—",
    ContentJP = "たとえ獣と化しても――",
    ContentKR = "짐승으로 변하더라도",
    ContentTC = "即使化身野獸——",
    TextMapContent = "即使化身野兽——",
    TextMapId = "voice_ch_char_Tuosi_vo_skill02_r01"
  },
  voice_ch_char_Tuosi_vo_skill02_r02 = {
    ContentEN = "Then take my heart—",
    ContentJP = "僕の心臓を捧げよう――",
    ContentKR = "그럼 내 심장을 포기하지",
    ContentTC = "那便捨棄我的心臟吧——",
    TextMapContent = "那便舍弃我的心脏吧——",
    TextMapId = "voice_ch_char_Tuosi_vo_skill02_r02"
  },
  voice_ch_char_Tuosi_vo_skill02_r03 = {
    ContentEN = "Even if all dreams are shattered.",
    ContentJP = "すべての夢が砕け散ったとしても。",
    ContentKR = "모든 꿈들이 이미 부서졌더라도.",
    ContentTC = "即使一切夢都已破碎。",
    TextMapContent = "即使一切梦都已破碎。",
    TextMapId = "voice_ch_char_Tuosi_vo_skill02_r03"
  },
  voice_ch_char_Tuosi_vo_topic_01_1 = {
    ContentEN = "He was a shattered crystal lamp, a fallen star plunged into a filthy gutter.",
    ContentJP = "粉々に砕けたガラスのランプ、下水道に落ちた星――ってところかな。",
    ContentKR = "그는 깨져버린 유리등이자, 시궁창에 떨어진 별.",
    ContentTC = "他是被摔碎的玻璃燈，是灑在汙水溝裡的星星。",
    TextMapContent = "他是被摔碎的玻璃灯，是洒在污水沟里的星星。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_01_1"
  },
  voice_ch_char_Tuosi_vo_topic_01_2 = {
    ContentEN = "He was just like those things — laughably absurd, yet somehow, they shine brilliantly.",
    ContentJP = "それらと同じように、思わず笑っちゃうほどバカバカしいのに、どこか眩しいやつだった。",
    ContentKR = "그것들과 마찬가지로 우스꽝스러우면서도 반짝반짝 빛나지.",
    ContentTC = "和那些東西一樣，荒誕的惹人發笑，卻又閃閃發亮。",
    TextMapContent = "和那些东西一样，荒诞得惹人发笑，却又闪闪发亮。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_01_2"
  },
  voice_ch_char_Tuosi_vo_topic_01_3 = {
    ContentEN = "The wall between our cells was so thin, every sound passed through. There he was, barely a metre away — rambling about his family, spinning dreams of the future, or singing some hopelessly off-key tune.",
    ContentJP = "僕たちの牢屋は壁一枚隔てられてるだけで、何もかもが筒抜けだった。あいつは1メートル先で、家族を思い出したり、未来を夢見たり、急に音痴な声で歌ってたな。",
    ContentKR = "우리의 감옥은 얇은 벽 하나만을 사이에 두고 있어서 방음이 절망적일 정도로 좋지 않았어. 그는 내가 볼 수 없는 그곳에서 가족들을 추억하고, 미래를 꿈꾸다가, 또 갑자기 정확하지 않은 음정으로 노래를 흥얼거리곤 했지.",
    ContentTC = "我們的牢房只隔著一道牆，隔音差得讓人絕望。他就在我看不見的一米之外，一會兒回憶家人，一會兒憧憬未來，一會兒又五音不全地哼起歌。",
    TextMapContent = "我们的牢房只隔着一道墙，隔音差得让人绝望。他就在我看不见的一米之外，一会儿回忆家人，一会儿憧憬未来，一会儿又五音不全地哼起歌。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_01_3"
  },
  voice_ch_char_Tuosi_vo_topic_01_4 = {
    ContentEN = "For a moment, I'd forget I was a caged beast. Instead, I'd feel like an ordinary child in school, waking from a nightmare during an afternoon nap to the racket of a noisy classmate beside me.",
    ContentJP = "そのせいか、僕は時折自分が檻に閉じ込められた獣ではなく、無邪気な学生だと錯覚することがある。午後の昼寝で悪夢にうなされてた時、隣の席の騒がしいクラスメイトに起こされたかのような気分になるんだ。",
    ContentKR = "가끔 난 울타리에 갇힌 짐승이 아니라, 걱정이 없는 평범한 학생이 된 기분이 들더라. 오후에 꾸벅 졸며 악몽을 꾸는데 옆자리의 시끄러운 급우 때문에 깬 것처럼.",
    ContentTC = "有時我甚至恍惚覺得，我不是被關在籠子裡的困獸，而是一個無憂無慮的普通學生，在午後打盹時做了個惡夢，被鄰座聒噪的同學吵醒了。",
    TextMapContent = "有时我甚至恍惚觉得，我不是被关在笼子里的困兽，而是一个无忧无虑的普通学生，在午后打盹时做了个噩梦，被邻座聒噪的同学吵醒了。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_01_4"
  },
  voice_ch_char_Tuosi_vo_topic_01_5 = {
    ContentEN = "...Heh. Perhaps.",
    ContentJP = "……まあ、そうかもね。",
    ContentKR = "...어쩌면.",
    ContentTC = "……呵，也許吧。",
    TextMapContent = "……呵，也许吧。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_01_5"
  },
  voice_ch_char_Tuosi_vo_topic_01_6 = {
    ContentEN = "But \"friend\" is far too bright a word for someone like me. We were more like two stranded fish, floundering together in a drying riverbed.",
    ContentJP = "けど、「友だち」という言葉はあまりに眩すぎる。僕にはその資格はないよ。干上がった川底に取り残された二匹の魚のようなものかな。",
    ContentKR = "하지만 '친구'란 말은 너무 눈부셔. 난 그걸 가질 자격이 없어. 어쩌면 그저 마른 강바닥에 남은 두 마리의 물고기가 더 어울릴 수도 있어.",
    ContentTC = "但「朋友」是一個過於耀眼的詞語，我不配擁有它。或許更應該算是，乾枯河床裡擱淺的兩條魚吧。",
    TextMapContent = "但“朋友”是一个过于耀眼的词语，我不配拥有它。或许更应该算是，干枯河床里搁浅的两条鱼吧。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_01_6"
  },
  voice_ch_char_Tuosi_vo_topic_02_1 = {
    ContentEN = "Why should I? Parsifal's story ended long ago. That name is but a distant echo now, so faint and far away that I sometimes wonder if it was ever real.",
    ContentJP = "なぜ？ 「パシファル」の人生はもう終わった。今となっては、どちらが本名だったか疑うほど、遠い記憶の断片に過ぎない。",
    ContentKR = "왜? '파르지팔'의 인생은 진작에 끝났어. 그 이름은 이미 너무 멀어져서, 가졌던 적이 있는지도 이젠 잘 모르겠더라.",
    ContentTC = "為什麼？「帕西法爾」的人生早已落幕。那個名字太遙遠了，遠到我懷疑自己是否曾真的擁有它。",
    TextMapContent = "为什么？“帕西法尔”的人生早已落幕。那个名字太遥远了，远到我怀疑自己是否曾真的拥有它。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_02_1"
  },
  voice_ch_char_Tuosi_vo_topic_02_2 = {
    ContentEN = "...Is that so?",
    ContentJP = "……そうか？",
    ContentKR = "...그런가?",
    ContentTC = "……是嗎？",
    TextMapContent = "……是吗？",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_02_2"
  },
  voice_ch_char_Tuosi_vo_topic_02_3 = {
    ContentEN = "Then I shall carry this final performance to its conclusion — for you, my last and only audience.",
    ContentJP = "まあいい。では、このラストショーを演じ続けるとしよう――僕の最後の、そして唯一の観客のために。",
    ContentKR = "좋아. 그럼 난 이 연극을 끝까지 해볼게. 내 마지막, 그리고 유일한 관객을 위해서.",
    ContentTC = "好吧。既然如此，我會把這最後一場戲一直演下去──為了我最後的、唯一的觀眾。",
    TextMapContent = "好吧。既然如此，我会把这最后一场戏一直演下去——为了我最后的、唯一的观众。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_02_3"
  },
  voice_ch_char_Tuosi_vo_topic_02_4 = {
    ContentEN = "Thank you, for granting me a stage to rest my weary soul.",
    ContentJP = "舞台にあげてくれて、ありがとう。",
    ContentKR = "고마워, 네 무대 위에 머무르게 해줘서.",
    ContentTC = "謝謝你，讓我停駐在你的舞台上。",
    TextMapContent = "谢谢你，让我停驻在你的舞台上。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_02_4"
  },
  voice_ch_char_Tuosi_vo_topic_03_1 = {
    ContentEN = "You're so kind. Thank you. Yet, all my vows have been fulfilled. There's little left that stirs my heart.",
    ContentJP = "お前は優しいな。だが、果たすべき約束は全て果たした。もう心残りはないよ。",
    ContentKR = "호의는 고맙지만, 내 약속은 다 지켰으니, 이제 더 이상 미련 같은 건 없어.",
    ContentTC = "多謝你的慷慨。但我的承諾都已兌現，我已經不再有什麼值得眷念的事。",
    TextMapContent = "多谢你的慷慨。但我的承诺都已兑现，已经不再有什么值得眷念的事。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_03_1"
  },
  voice_ch_char_Tuosi_vo_topic_03_3 = {
    ContentEN = "Should you ever find yourself at the Galea Theatre, please convey to Ms Violetta that I've settled down in Aethyrie. Assure her not to worry, as I am doing very well now.",
    ContentJP = "ガレア劇場に、僕の先生だったヴィオレッタさんがいるんだ。もしもいつか出会ったら、僕はイーザーで幸せに暮らしてるから、心配しないでって伝えてくれないか？",
    ContentKR = "만약 언젠가 갈레아 극장에서 나의 스승님 비올레타 여사님을 만나게 된다면 전해줘. 난 이미 이스엘에서 자리를 잡고 잘 지내니 걱정하지 말라고.",
    ContentTC = "若你有一天在蓋雷亞劇院遇到我的恩師薇奧萊塔女士，請轉告她，我已在伊瑟爾定居。現在過得很好，請不要擔憂。",
    TextMapContent = "若有一天你在盖雷亚剧院遇到我的恩师薇奥莱塔女士，请转告她，我已在伊瑟尔定居。现在过得很好，请不要担忧。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_03_3"
  },
  voice_ch_char_Tuosi_vo_topic_03_4 = {
    ContentEN = "\"A land of music and poetry, where every pebble taps out a rhythm, and every brook sings a melody.\"",
    ContentJP = "「そこは音楽と詩の国で、小石すらリズムを刻み、泉の水すら旋律を奏でてるんだ」って。",
    ContentKR = "\"조약돌 하나하나가 장단을 치고, 샘물 하나하나가 선율을 노래하는 음악과 시의 나라.\"",
    ContentTC = "「那是音樂與詩的國度，那裡的每一顆卵石都敲擊著節拍，每一泓泉水都歌唱著旋律。」",
    TextMapContent = "“那是音乐与诗的国度，那里的每一颗卵石都敲击着节拍，每一泓泉水都歌唱着旋律。”",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_03_4"
  },
  voice_ch_char_Tuosi_vo_topic_03_5 = {
    ContentEN = "Hopefully, that'll keep her from enquiring after me. Once her favoured pupil... I'd rather not tarnish her memories.",
    ContentJP = "それで僕を探すのを諦めてくれるといいが……僕は先生の自慢の生徒だったからな。僕のせいで彼女に恥をかかせたくないんだ。",
    ContentKR = "그러면 스승님께선 아마 더 이상 내 행방을 묻지 않겠지. 난 그녀의 가장 자랑스러운 제자였으니까... 그녀가 나 때문에 창피당하는 건 원치 않아.",
    ContentTC = "這樣一來，或許她就不會再打聽我的下落了。我曾是她欣賞的學生……我不希望她因我蒙羞。",
    TextMapContent = "这样一来，或许她就不会再打听我的下落了。我曾是她欣赏的学生……我不希望她因我蒙羞。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_03_5"
  },
  voice_ch_char_Tuosi_vo_topic_03_6 = {
    ContentEN = "Indeed. Ignorance is always bliss.",
    ContentJP = "うん、何も知らないほうが幸せなこともあるからな。",
    ContentKR = "그래. 아무것도 모르면 더 행복하겠지.",
    ContentTC = "嗯，一無所知總會是更加幸福的。",
    TextMapContent = "嗯，一无所知总会是更加幸福的。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_03_6"
  },
  voice_ch_char_Tuosi_vo_topic_04_1 = {
    ContentEN = "Why seek to learn acting? You have no need to become someone else.",
    ContentJP = "なぜだ？お前はお前だ。他人に成りきる必要はない。",
    ContentKR = "왜 연기를 배우려 하는 거지? 넌 그 누구도 될 필요 없어.",
    ContentTC = "為什麼想學表演？你不需要變成任何人。",
    TextMapContent = "为什么想学表演？你不需要变成任何人。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_04_1"
  },
  voice_ch_char_Tuosi_vo_topic_04_2 = {
    ContentEN = "When you're on stage, every part of you — from your very bones to the breaths you take — is surrendered to the character. In that moment, you can shed all your sorrows and pain, stepping into a world unblemished by reality.",
    ContentJP = "舞台に立った時、その体と呼吸のすべてを演技に捧げれば、お前は完全に別人となれるんだ。その瞬間、初めて自分を苦しめたすべてを忘れ、未知の世界に踏み出すことができる。",
    ContentKR = "무대에선 모든 뼈마디와 숨결까지 공연에 바친다면, 완전히 다른 사람이 될 수 있지. 고통을 가져다주는 모든 걸 잊고 새로운 세계로 갈 수 있어.",
    ContentTC = "只要站在舞台上，把你的每一寸骨骼，每一縷氣息奉獻給演出，你就可以徹底變成另一個人，忘記帶給你痛苦的一切，走向你前所未見的世界。",
    TextMapContent = "只要站在舞台上，把你的每一寸骨骼，每一缕气息奉献给演出，你就可以彻底变成另一个人、忘记带给你痛苦的一切，走向你前所未见的世界。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_04_2"
  },
  voice_ch_char_Tuosi_vo_topic_04_3 = {
    ContentEN = "But you... you were born the {性别：hero|heroine} of your own story, already carrying the admiration and trust of those around you. You shine effortlessly, needing no spotlight to dazzle.",
    ContentJP = "とはいえ、お前は生まれた瞬間から冒険物語で祝福を受けた主人公になると決まっていた。すべての登場人物がお前を注目し信用するだろう。舞台がなくとも、お前は十分輝かしい存在だ。",
    ContentKR = "하지만 넌 모험담의 축복받는 주인공으로 태어나 모든 이의 주목과 신뢰를 받고 있잖아. 무대 없이도 충분히 밝게 빛날 수 있어.",
    ContentTC = "但你生而就是一位冒險故事裡被祝福的主人公，擁有所有角色的矚目和信賴。你無需舞台，便足以熠熠生輝。",
    TextMapContent = "但你生而就是一位冒险故事里被祝福的主人公，拥有所有角色的瞩目和信赖。你无需舞台，便足以熠熠生辉。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_04_3"
  },
  voice_ch_char_Tuosi_vo_topic_05_1 = {
    ContentEN = "It stands, enduring time far beyond my years. On one side of its towering walls lies the imposing inner city — majestic as storm clouds, yet colder.",
    ContentJP = "あれは僕が生まれるよりずっと前からそこに佇んでいた。その外壁の向こうには、そびえ立つ内城区があり――雲のように高く、雲よりずっと寒い場所だ。",
    ContentKR = "극장은 나보다 훨씬 더 오랜 세월 동안 그 자리를 지켰어. 외벽 쪽엔 먹구름보다 높고 더 차갑게 우뚝 솟은 내성이 있지.",
    ContentTC = "它站在那兒，歷經遠比我的生命悠長的歲月。在它外牆的這一邊，是巍峨的內城，和烏雲一樣高，比烏雲更冷。",
    TextMapContent = "它站在那儿，经历远比我的生命悠长的岁月。在它外墙的这一边，是巍峨的内城。和乌云一样高，比乌云更冷。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_05_1"
  },
  voice_ch_char_Tuosi_vo_topic_05_2 = {
    ContentEN = "Elegantly clad figures alight from silk-lined carriages, discussing art, poetry, and the perpetual gloom of the skies. They gossip about balls and betrothals, lamenting how the mire of melting snow from the outer city soils their fine leather boots.",
    ContentJP = "絹に包まれた馬車から降りてくる人々は、曇り続きの天気を語り、詩や絵画、舞踏会や結婚式の話をしながら、外城区から流れ込む汚れた雪水が上品な革靴を汚すことに不満を漏らしていた。",
    ContentKR = "사람들은 비단으로 감싸진 마차에서 내리며 좀처럼 맑아지지 않는 날씨와 시, 그림, 무도회, 혼사에 관해 얘기를 해. 또 아름다운 가죽 부츠를 얼룩지게 하는 외성의 더러운 눈을 불평하면서 말이야.",
    ContentTC = "人們從裹著絲綢的馬車走來，談論總不放晴的天氣，談論詩歌與繪畫，談論舞會與婚事，抱怨外城污濁的雪水弄髒了漂亮的皮靴。",
    TextMapContent = "人们从裹着丝绸的马车走来，谈论总不放晴的天气，谈论诗歌与绘画，谈论舞会与婚事，抱怨外城污浊的雪水弄脏了漂亮的皮靴。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_05_2"
  },
  voice_ch_char_Tuosi_vo_topic_05_3 = {
    ContentEN = "On the other side of the walls, the rowdy fog district buzzes with chaos. Vendors hawk loudly, mothers clutch their children, begging for a scrap of rye bread. Mischievous hands sketch defiant graffiti, always a step ahead of the patrols.",
    ContentJP = "外壁のもう一方には、賑やかな霧の街が広がっている。そこでは、声を張り上げて客引きする屋台の商人や子供たちを抱えて黒パンを乞う母親、さまざまな人たちが暮らしていた。警備員の目を盗んで、壁に落書きをする者もいたな。",
    ContentKR = "외벽의 반대쪽은 시끄러운 안개 지역이야. 그곳에선 노점상들은 큰 소리로 물건을 팔고, 어머니는 굶주린 아이를 안고 빵 한 조각을 구걸해. 일 벌이길 좋아하는 사람들은 위병들의 눈을 피해 벽에 낙서하고 있어.",
    ContentTC = "外牆的另一側，是嘈雜的霧區。在那裡，小販扯尖嗓子叫賣，母親抱著自己的孩子，乞求一片黑麵包果腹。好事者一邊躲著衛兵，一邊在牆上塗鴉。",
    TextMapContent = "外墙的另一侧，是嘈杂的雾区。在那儿，小贩扯尖嗓子叫卖，母亲抱着自己的孩子，乞求一片黑面包果腹。好事者一边躲着卫兵，一边在墙上涂鸦。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_05_3"
  },
  voice_ch_char_Tuosi_vo_topic_05_4 = {
    ContentEN = "And so stands our Galea Theatre, caught between these two worlds, hearing all yet understanding none.",
    ContentJP = "それが僕たちのガレア劇場だ。 劇場はそこに在り、それらの声に耳を傾けるが、理解することはない。",
    ContentKR = "그게 우리 갈레아 극장이야. 그저 우뚝 서서 그 소리를 듣지만, 또 그 소리를 알아듣지 못하지.",
    ContentTC = "這就是我們的蓋雷亞劇院。它站在那兒，聽著這些聲音，但又聽不懂這些聲音。",
    TextMapContent = "这就是我们的盖雷亚剧院。它站在那儿，听着这些声音，但又听不懂这些声音。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_05_4"
  },
  voice_ch_char_Tuosi_vo_topic_05_5 = {
    ContentEN = "Oddly, it's not the scripts or the lavish costumes that first come to mind, nor the cluttered prop room I swept daily.",
    ContentJP = "……なぜだか、真っ先に思い出したのは、様々な脚本でも、派手な衣装やアクセサリーでも、毎日掃除をしていた小さな道具部屋でもなかった。",
    ContentKR = "...왜인지 모르겠지만, 처음 떠오르는 건 대본도, 화려한 의상과 장신구도, 심지어 매일 청소하는 소품실도 아니야.",
    ContentTC = "……不知為什麼，我第一個想起的不是各種劇本，不是花俏的戲服和首飾，甚至不是每天打掃的小道具間。",
    TextMapContent = "……不知为什么，我第一个想起的不是各种剧本，不是花哨的戏服和首饰，甚至不是每天打扫的小道具间。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_05_5"
  },
  voice_ch_char_Tuosi_vo_topic_05_6 = {
    ContentEN = "It's the velvet carpet that blanketed the stage after the curtain fell. As a child, after the earliest performance I can remember, my mother and I lingered on the stage after everyone left, reciting lines and dancing through the night.",
    ContentJP = "幕引きのあと、舞台に敷かれたあの薄い絨毯が今でも忘れられない。子供の頃、初めての公演が終わったあと、母とそこで劇の歌詞を繰り返し歌い、一晩中踊ったことを思い出すんだ。",
    ContentKR = "그저 공연이 끝나고 무대 위에 펼쳐진 얇은 담요가 생각나. 어린 시절, 기억 속의 첫 공연이 끝나고 나랑 어머니는 그곳에서 극 중 가사를 반복하며 밤새 춤췄어.",
    ContentTC = "我想起的是演出落幕後，舞台上那襲薄毛毯。小時候，記憶裡的第一場演出結束後，我和母親在那兒重複著劇裡的唱詞，跳了整夜的舞。",
    TextMapContent = "我想起的是演出落幕后，舞台上那袭薄绒毯。小时候，记忆里的第一场演出结束后，我和母亲在那儿重复着剧里的唱词，跳了整夜的舞。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_05_6"
  },
  voice_ch_char_Tuosi_vo_topic_05_7 = {
    ContentEN = "When dawn broke, exhaustion finally overtook me. I lay down on that carpet, resting my head on Mother's lap, and drifted into a long, sweet dream.",
    ContentJP = "朝日がちらつく頃、疲れた僕は母の両膝に頭をのせ、その絨毯の上で長い夢を見るんだ。",
    ContentKR = "해가 뜰 무렵, 난 피곤해져 어머니 무릎을 베고 그 담요 위에 누웠지. 그리고 긴 꿈을 꿨어.",
    ContentTC = "日出時分我累了，就躺在那襲絨毯上，枕著她的兩膝，做了一個長長的夢。",
    TextMapContent = "日出时分我累了，就躺在那袭绒毯上，枕着她的两膝，做了一个长长的梦。",
    TextMapId = "voice_ch_char_Tuosi_vo_topic_05_7"
  },
  voice_ch_char_Tuosi_vo_victory = {
    ContentEN = "Comedy is the satire of the wise.",
    ContentJP = "喜劇は賢者の皮肉である。",
    ContentKR = "희극은 현자의 풍자.",
    ContentTC = "喜劇是智者的譏諷。",
    TextMapContent = "喜剧是智者的讥讽。",
    TextMapId = "voice_ch_char_Tuosi_vo_victory"
  },
  voice_ch_char_Tuosi_vo_welcome = {
    ContentEN = "I assume the role of the shattered prisoner, and you, as a watchful warden, stand sentinel over my chains.",
    ContentJP = "僕は傷だらけの囚人役で、君はその僕を縛り付ける監守役だ。",
    ContentKR = "이제 난 부서진 죄수의 역할이고, 넌 나한테 족쇄를 채우는 교도소장이네.",
    ContentTC = "如今我扮演破碎的囚徒，而你是為我執掌枷鎖的典獄長。",
    TextMapContent = "如今我扮演破碎的囚徒，而你是为我执掌枷锁的典狱长。",
    TextMapId = "voice_ch_char_Tuosi_vo_welcome"
  },
  voice_ch_char_Xibi_vo_appear = {
    ContentEN = "Seeking aid from an enemy? Good, it seems hatred hasn't completely clouded your judgment.",
    ContentJP = "敵に助けを乞う覚悟があるなんて、賢いじゃない。あなたの理性はまだ憎しみに吞まれていないようね。",
    ContentKR = "적에게 도움 요청이라니, 좋다. 아직 원한이 네 이성을 집어삼키지 않은 것 같군.",
    ContentTC = "願意向敵人伸手求援，很好，看來仇恨尚未吞噬你的理性。",
    TextMapContent = "愿意向敌人伸手求援，很好，看来仇恨尚未吞噬你的理性。",
    TextMapId = "voice_ch_char_Xibi_vo_appear"
  },
  voice_ch_char_Xibi_vo_battleidle = {
    ContentEN = "No slacking; in the Legion, you'd have felt the whip by now.",
    ContentJP = "ぐずぐずしないで。帝国軍属であれば懲罰ものよ。",
    ContentKR = "게으름 피우지 마라. 군단이었다면 진작에 채찍을 맞았을 거다.",
    ContentTC = "別偷懶，要是在軍團你已經吃鞭子了。",
