  voice_ch_char_Xibi_vo_gain = {
    ContentEN = "I know what you wish to ask, but you're not yet strong enough to warrant my response. So, lay down your weapon; that's the kindest advice I can offer.",
    ContentJP = "お前の知りたいことはお見通しよ。でもいまの実力じゃ、私から答えすら引き出せないでしょうね。わかったなら剣を納めなさい。私がお前にしてやれる唯一の、善意に基づいた助言よ。",
    ContentKR = "뭘 묻고 싶은지 안다. 하지만 아직 내가 대답하도록 만들기엔 힘이 부족하군. 그러니 일단 검을 내려놔라. 지금 웃으면서 좋게 말할 때.",
    ContentTC = "我知道你想要問什麼，但現在的你，還沒有足以讓我給予答覆的力量。所以，先放下劍，這是我對你最善意的建議。",
    TextMapContent = "我知道你想要问什么，但现在的你，还没有足以让我给予答复的力量。所以，先放下剑，这是我对你最善意的建议。",
    TextMapId = "voice_ch_char_Xibi_vo_gain"
  },
  voice_ch_char_Xibi_vo_idle = {
    ContentEN = "Exposing your back to your enemy so carelessly... Is it naivety or sheer folly?",
    ContentJP = "よくもまあ簡単に、敵に背中を晒すわね？無邪気と言うべきか、愚かと言うべきか。",
    ContentKR = "이렇게 쉽게 적에게 등을 보이다니... 순진하다고 해야 하나, 어리석다고 해야 하나?",
    ContentTC = "居然把後背輕易暴露給自己的敵人…… 該說你天真還是愚蠢？",
    TextMapContent = "居然把后背轻易暴露给自己的敌人……，该说你天真还是愚蠢？",
    TextMapId = "voice_ch_char_Xibi_vo_idle"
  },
  voice_ch_char_Xibi_vo_lvup = {
    ContentEN = "Ascend relentlessly, or be consumed by the abyss.",
    ContentJP = "奈落に墜ちたくなければ、絶えず這い上がるしかないの。",
    ContentKR = "계속 위로 올라가야만 심연에 빠지지 않을 수 있다.",
    ContentTC = "唯有不斷向上，才能不墜入深淵。",
