  voice_ch_char_Xibi_vo_skill02_r01 = {
    ContentEN = "Pathetic weaklings.",
    ContentJP = "クズが、一撃でも耐えられると思わないで。",
    ContentKR = "상대할 가치도 없는 무능한 것.",
    ContentTC = "不堪一擊的廢物。",
