  voice_ch_char_Zhangyu_vo_appear = {
    ContentEN = "Are we going on an adventure today?",
    ContentJP = "どこに遊びにいくんだ？",
    ContentKR = "어디로 놀러 갈 거야?",
    ContentTC = "要去哪玩？",
    TextMapContent = "要去哪玩？",
